-- GENERATED by `wfj generate` from data/quest/quest-0002.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [2038] = { "Gli attrezzi perduti di Bingles", "Trova e riporta gli attrezzi di Bingles:\n\nChiave Meccanica di Bingles, ⟦Bingles' Screwdriver=Cacciavite di Bingles⟧, ⟦Bingles' Hammer=Martello di Bingles⟧ e ⟦Bingles' Blastencapper=Scoppiabarile di Bingles⟧.", "Come se precipitare nel lago non fosse già abbastanza, i trogg dell'isola qui vicino mi hanno attaccato e rubato gli attrezzi e gli speciali esplosivi Scoppiabarile Blastenheimer. Senza girocottero e senza esplosivi, il movimento non ha speranze!\n\nRiprendi i miei attrezzi e trova i miei esplosivi Scoppiabarile, {name}. Per Gnomeregan!", "{name}! Dove sono le mie cose?!", "Hai reso un grande servizio al movimento, {name}. I trogg e gli gnomi lebbrosi che infestano Gnomeregan sentiranno presto tutto il peso di un assalto aereo gnomesco!", 0xf9774368, 0x792008cf, 0xd09399c8, 0x1dd7bb2d, 0x5ee96793, "....." },
  [2039] = { "Alla ricerca di Bingles", "Trova Bingles Blastenheimer a Loch Modan.", "Abbiamo perso i contatti con Bingles! Era stato mandato in missione di ricognizione sopra Gnomeregan e non fa rapporto da più di una settimana. Me lo sento, è andato a farsi saltare in aria.\n\nL'ultima volta è stato visto sorvolare il lago. Forse puoi indagare tu, {name}.", nil, "Quindi Gnoarn non si fida delle mie capacità di ricognizione? Chissà perché...\n\nLasciamo perdere, ho bisogno del tuo aiuto! No! Il movimento ha bisogno del tuo aiuto!", 0x615905ca, 0x3376ba72, 0x0eb9eb85, nil, 0xe10b4d25, "...m." },
  [2040] = { "Assalto sotterraneo", "Recupera il ⟦Gnoam Sprecklesprocket=Sarchiapone⟧ dalle ⟦Deadmines=Miniere della Morte⟧ e riportalo a Shoni the Shilent, a ⟦Stormwind=Roccavento⟧.", "Gnomeregan è caduta sotto il controllo di quei maledetti trogg! La situazione è grave, ma forse tu puoi aiutarci, {name}.\n\nNel profondo delle ⟦Deadmines=Miniere della Morte⟧ c'è un trituratore goblin funzionante. Trova quel trituratore e riporta indietro il suo generatore intatto. Con il generatore del trituratore potremo dare ai nostri girotrivellatori escavatronici l'energia che serve a sfondare i confini rocciosi sotterranei di Gnomeregan, aprendo la strada a un assalto gnomesco!", "Hai trovato il ⟦Gnoam Sprecklesprocket=Sarchiapone⟧, {name}?", "Ben fatto, {name}. Grazie a te, Gnomeregan è un passo più vicina al giorno della sua liberazione!", 0x80a0cba5, 0xea953ef0, 0x63b95920, 0x9b272279, 0x733d0acf, "....." },
  [2041] = { "Un colloquio con Shoni", "Parla con Shoni the Shilent a ⟦Stormwind=Roccavento⟧.", "Forse... Forse puoi aiutarci nella battaglia per Gnomeregan.\n\nA ⟦Stormwind=Roccavento⟧ troverai il comandante della nostra squadra d'assalto sotterraneo, Shoni the Shilent. Shoni ha bisogno di aiuto con i suoi escavatorizzatori girotrapanomatici.\n\nProbabilmente la troverai in mezzo ai nani di ⟦Stormwind=Roccavento⟧.\n\nBuona fortuna, {name}.", nil, "Porti notizie dal comando centrale?", 0xf9384378, 0xe35660ac, 0xa17f2e67, nil, 0xc9cd2431, "...m." },
  [2078] = { "La vendetta di Gyromast", "Trova il primo ufficiale di Gelkak, il Threshwackonator 4100, e riaccompagnalo da Gelkak.", "Marinaio d'acqua dolce, devi trovare il mio primo ufficiale.\n\nPrendi 'sta chiave, ficcagliela in zucca e riportalo qui a servire il Capitano.\n\nQuei murloc e il loro capo non saranno tanto contenti quando il mio primo ufficiale li avrà tra le grinfie!", "Dov'è il mio primo ufficiale, {name}? Catene e squali per te se non ti sbrighi!", "Arrr... Stai dimostrando di essere più di un lupo di mare codardo, marinaio d'acqua dolce.\n\nIl Capitano potrebbe promuoverti a mozzo del cassero di poppa, se continui così...", 0xd9963931, 0xd2b23f5c, 0x7ec45f79, 0x4a2ccf6d, 0xa5444273, "....." },
  [2098] = { "Il recupero di Gyromast", "Trova i tre pezzi della Chiave di Gelkak e riportali a Gelkak Gyromast.", "La vita del pirata non è facile, marinaio d'acqua dolce. Non è solo saccheggi e grog! Ahimè, la mia nave è affondata proprio al largo per colpa di quei maledetti plesiosauri.\n\nQuel che mi serve è il mio primo ufficiale di nuovo funzionante!\n\nQuando sono finito a riva, la chiave del mio primo ufficiale si è rotta sugli scogli ed è stata arraffata dalle bestiacce di ⟦Darkshore=Rivafosca⟧. Con la coda dell'occhio ho visto alcuni di quei Ragin' Crawler, Ferocious Foreststrider e murloc frugare tra i rottami....", "L'hai trovata la mia chiave rotta, marinaio d'acqua dolce?", "Ohè, lurido lupo di mare! Ce l'hai fatta! Presto il mio primo ufficiale sarà di nuovo funzionante e quelle bestiacce non sapranno cosa le ha colpite!\n\nMmm, hai visto il mio primo ufficiale?", 0xfb8edee7, 0xb52c5a6e, 0x1f7e89e6, 0x5badcb40, 0x8453295d, "....." },
  [2118] = { "Terre appestate", "Cattura un Rabid Thistle Bear vivo e portalo da Tharnariun.\n\nSe non riesci a catturare un Rabid Thistle Bear e perdi la trappola, torna da Tharnariun Treetender e chiedine un'altra.", "Un morbo si diffonde per ⟦Darkshore=Rivafosca⟧ e si impadronisce della mente e del corpo di chiunque tocchi.\n\nI Thistle Bear sono stati colpiti più duramente di tutti da questa piaga. Un tempo bestie nobili, ora sono strumenti di distruzione, rabbiosi e frenetici. Forse ho una cura per questo male.\n\nPorta questa trappola nella foresta e posala a terra. Ogni Rabid Thistle Bear che attraverserà la luce diventerà docile per breve tempo. Una volta docile, l'orso ti seguirà. Riportalo qui, {name}.", "Mi hai portato l'animale malato, {name}?\n\nSe non riesci a far scattare la trappola, non preoccuparti: la ⟦Tharnariun's Hope=Speranza di Tharnariun⟧ è eterna. Se ti serve un'altra trappola, abbandona il compito e torna da me.", "Il nostro lavoro è appena cominciato, {name}. Sei pront<o/a> per il prossimo compito?", 0xfa0a3a70, 0x3807aa6c, 0xe76e9858, 0xcaf47f66, 0xb17abac8, "....." },
  [2138] = { "La purificazione degli infetti", "Ripulisci la foresta da 20 Rabid Thistle Bear e torna da Tharnariun Treetender a ⟦Darkshore=Rivafosca⟧.", "Come temevo, la cura non funziona.\n\nMi rattrista profondamente ordinare la morte di una qualunque creatura della natura, ma gli orsi dei cardi malati e contaminati devono essere abbattuti.\n\nTorna nella foresta e distruggi 20 orsi dei cardi rabbiosi, {name}. Di certo non fermerà la piaga, ma per un po' rallenterà i danni che questi animali stanno facendo alla nostra foresta e ai suoi abitanti.", "Hai portato a termine il tuo compito?", "Hai reso un grande servizio ad Auberdine, {name}, ma il tuo compito non è ancora finito.\n\nTorna da me quando ti sarai riposat<o/a>.\n\n...e {name}, prepara la mente e l'anima ad altro spargimento di sangue.", 0x6f6f3496, 0x02dfdd6a, 0x7195c76b, 0x79783cba, 0x6c182eed, "....." },
  [2139] = { "⟦Tharnariun's Hope=Speranza di Tharnariun⟧", "Trova e uccidi la Den Mother.", "La sopravvivenza del nostro popolo e delle nostre terre ha un prezzo doloroso, {name}.\n\nHai versato il sangue dei servitori della natura; hai abbattuto molti animali malati. La gente di Auberdine è in debito con te, perché il dolore della foresta si è attenuato, anche se solo per un momento.\n\nHo un ultimo compito per te, ma ti avverto: dovrai uccidere ancora. Spero che sia l'ultima volta che ti chiamo, {name}.\n\nIn una caverna a nord-est, vicino a ⟦Bashal'Aran=Bashal'aran⟧, vive la Den Mother. Uccidila.", "Con la Den Mother infetta uccisa, il numero di Rabid Thistle Bear che entrano nelle nostre terre diminuirà. Non perdere tempo, {name}.", "Hai combattuto per Auberdine con coraggio e onore, {name}. Nelle nostre terre dilaniate dalla guerra, morte e disperazione sono all'ordine del giorno. Molti non sapranno affrontare la sfida della vita nella nostra nuova patria e sceglieranno invece di nascondersi nelle loro case o di fuggire nelle terre più fortificate dell'⟦Alliance=Alleanza⟧.\n\nGrazie, {name}. Forse un giorno non lontano combatteremo fianco a fianco come compagni contro un altro nemico.", 0xf10fef91, 0x4766c644, 0xe4256bfb, 0x3c698219, 0x8e54a76e, "....." },
  [2158] = { "Riposo e relax", "Parla con il locandiere Farley alla Lion's Pride Inn.", "Ogni avventuriero dovrebbe riposare quando arriva la stanchezza, e non c'è posto migliore per riposo e relax della Lion's Pride Inn!\n\nIl mio migliore amico, il locandiere Farley, gestisce la Lion's Pride. Se gli dici che ti mando io, forse ti farà i prezzi speciali scontati su cibo e bevande.\n\nPer trovare la Lion's Pride Inn, segui la strada verso sud da qui: non puoi sbagliare!", nil, "Riposo e relax per gli stanchi e gli infreddoliti: è il nostro motto! Prego, siediti accanto al fuoco e riposa le tue stanche ossa.\n\nTi va di assaggiare un po' del nostro ottimo cibo e delle nostre bevande?", 0xf6b2744d, 0xf61951e2, 0xff0677e6, nil, 0x6e2b261e, "...m." },
  [2159] = { "⟦Dolanaar Delivery=Pacco per Dolanaar⟧", "Porta il ⟦Dolanaar Delivery=Pacco per Dolanaar⟧ alla locandiera Keldamyr.", "Salute, giovane {class}. Puoi darmi una mano? Ho un pacco di erbe da consegnare al villaggio di Dolanaar. Ma ho ancora degli affari con i druidi di ⟦Shadowglen=Vallombra⟧ e non posso ancora partire.\n\nPuoi consegnare questo pacco per me? Va portato alla locandiera Keldamyr, alla locanda di Dolanaar. Si trova lungo la strada, a sud.", "Come posso esserti utile, giovane? Sei qui per riposare alla locanda? Ti serve una Pietra del Ritorno?", "Ah sì, la consegna di erbe da ⟦Shadowglen=Vallombra⟧. Peccato che Porthannius non abbia potuto portarla di persona, perché abbiamo molto di cui parlare, io e lui. Ma sono comunque lieta di avere le erbe, e sono lieta che tu sia venut<o/a>.\n\nFinché sei qui, ti prego, riposati. Gli eroi devono mantenere alti la forza e lo spirito, e devono trovare riposo e conforto ogni volta che possono. Perché trascurare la pace del corpo e della mente è una via sicura verso il fallimento.\n\nQuindi... riposa.", 0x1821b05c, 0x63d50e5c, 0xc4d46c8a, 0x4944e9aa, 0x1a7ac861, "....." },
  [2160] = { "Scorte per Tannok", "Consegna la ⟦Crate of Inn Supplies=Cassa di Scorte della Locanda⟧ a Tannok Frosthammer, a Kharanos.", "Ehi! Hai l'aria di una persona avventurosa e in gamba. Se hai intenzione di sfidare il passo, potresti portare un pacco alla locanda di Kharanos?\n\nPensavi di fermarti alla locanda, no? Se riesci a superare il passo, di sicuro vorrai riprendere fiato lì.\n\nComunque, porta questo a Tannok Frosthammer, l'aiutante del locandiere. Io non riesco a passare, e ci vorranno giorni prima che arrivi una scorta di montanari!", "Ciao! Entra, siediti vicino al fuoco e scaldati con un boccale di birra.", "Ah, finalmente, le scorte da Hands! Cominciavo a preoccuparmi: abbiamo avuto ben poche notizie da ⟦Anvilmar=Forgiamara⟧ da quando i trogg hanno invaso il passo.\n\nGrazie per avermele portate, {name}. E ti prego, mettiti comod<o/a>. Devi essere stanc<o/a> dopo il viaggio.", 0x1a599de9, 0xec5c9fbf, 0x3e311c16, 0xd1d47487, 0xe882bc33, "....." },
  [2161] = { "Il fardello di un peone", "Porta il ⟦Ukor's Burden=Fardello di Ukor⟧ al locandiere Grosk, a ⟦Razor Hill=Tranciacolle⟧.", "Scusa? Puoi aiutarmi?\n\nHo qui un carico di cibo. Ho camminato lungo la strada e ho affrontato scorpidi, ragni e di peggio! Ho portato il cibo alla ⟦Valley of Trials=Valle delle Sfide⟧ perché pensavo che ne avessero bisogno e a me piace dare una mano. Ma il cibo non gli serve! Ora devo riportarlo a ⟦Razor Hill=Tranciacolle⟧ e ho paura di tutte le bestie lungo la strada...\n\nPuoi portarlo tu per me? Io sono solo un peone, ma tu sei della stoffa degli eroi. Non hai paura di niente!\n\nPortalo al locandiere Grosk, alla locanda di ⟦Razor Hill=Tranciacolle⟧. Grazie!", "Benvenut<o/a> a ⟦Razor Hill=Tranciacolle⟧!", "Ah, questo è il cibo che Ukor ha portato alla ⟦Valley of Trials=Valle delle Sfide⟧. Non ne avevano bisogno? Be', a quanto pare là gli piace far patire la fame a voi eroi in addestramento. Tempra lo spirito, dicono!\n\nGrazie per aver riportato il cibo. Lo rimetterò sugli scaffali... ma prima lascia che ti offra qualcosa per rifocillarti!\n\nE non dimenticare di riposare qui alla locanda. Sarai anche <un/una> {class} <coraggioso/coraggiosa> e <pronto/pronta> a conquistare il mondo, ma se sei senza energie non farai un granché di buono né a te stess<o/a> né all'⟦Horde=Orda⟧.", 0x7aa7b221, 0xde148f6a, 0xcd75d4e8, 0x4bc9da1c, 0xef14d510, "....." },
  [2178] = { "La dolce vita degli zampalunga", "Riporta 5 ⟦Strider Meat=Carne di Zampalunga⟧ ad Alanndarian Nightsong ad Auberdine.", "Senti che profumino delizioso? È la mia ricetta segreta, {name}: stufato di zampalunga fresco. Una delizia!\n\nTi interesserebbe forse imparare la ricetta?\n\nPrima che te la insegni, dovrai dimostrare di saper tenere testa a quelle bestie.\n\nOra, non pretendo che tu vada a domarne uno e me lo riporti in sella, ma se riesci a ucciderne qualcuno e a portarmi un po' della loro carne succulenta, potrei lasciarmi convincere a svelarti i segreti dello stufato di zampalunga.", "La pentola è vuota e io ho fame! Perché ci metti tanto?", "Fantastico! Assaggialo e dimmi cosa ne pensi, {name}!", 0xfb77df5a, 0xccc0962f, 0x0abb668a, 0xe34f9c3e, 0x42580f7f, "....." },
  [2205] = { "In cerca del SI: 7", "Consegna il pacco di Keryn Sylvius a mastro Mathias Shaw, nella caserma di ⟦Stormwind=Roccavento⟧.", "Il distintivo? Oh, non è niente, pivell<o/a>: niente che tu possa gestire, comunque. A giudicarti dall'aspetto, direi che Mathias ti scambierà per <il/la> <ragazzo/ragazza> che consegna il formaggio, invece che per <un/una> ver<o/a> <ladro/ladra>. In ogni caso, mi è stato assegnato un incarico e ho promesso di portarlo a termine.\n\nA proposito, consegna questo pacco a Mathias e forse ti affiderà un compito o due.\n\nDatti una mossa.", "Posso aiutarti, {class}?", "Mi hai trovato... e a giudicare dal tuo aspetto, direi che la corsa e la ricerca che ne è seguita ti abbiano messo a dura prova, sia nella mente sia nel corpo.\n\nVuoi che Renzik ti mostri la strada per una locanda o sei pront<o/a> per un po' di lavoro?", 0xcaa7a9f9, 0x07f738a1, 0xfb528bff, 0x01686e7d, 0xde7424bd, ".....", nil, nil, 0x454725db, nil, nil },
  [2206] = { "Arraffa e scappa", "Trova il Defias Dockmaster e recupera lo Shipping Schedule per mastro Mathias Shaw.", "I nostri agenti sul campo riferiscono un'intensa attività dei Defias a sud di ⟦Goldshire=Borgodoro⟧. Secondo i rapporti, i Defias si sono impadroniti del ⟦Jerod's Landing=Molo di Jerod⟧ e ora lo usano per contrabbandare grandi quantità di merce da ⟦Redridge=Crestarossa⟧ alle ⟦Westfall=Marche Occidentali⟧.\n\nHo bisogno che ti infiltri nella casa del molo e mi porti quel registro delle spedizioni, {name}. Probabilmente lo troverai in fondo alle tasche del Dockmaster.\n\n...e {name}, se dovessi essere scopert<o/a>, l'⟦SI:7=IR:7⟧ negherà di sapere alcunché della tua esistenza.", "Il tuo tempo da mortale si consuma a ogni istante che sprechi a bighellonare in caserma, {class}.", "Sono sbalordito... Sbalordito che Keryn abbia finalmente trovato una recluta che potrebbe avere la stoffa di un vero ladro. Prendi questa lama, {name}. Verrà il giorno in cui sarai chiamat<o/a> di nuovo a servire l'⟦SI:7=IR:7⟧. Affina le tue abilità, tieni gli occhi aperti e quella lama affilata.\n\nNon ci vedrai arrivare, ma te ne accorgerai quando saremo lì...", 0x1787987c, 0x494cbf92, 0xb285531c, 0xcd220e78, 0x0bc8224c, "....." },
  [2218] = { "La via della salvezza", "Parla con Hulfdan Blackbeard a ⟦Ironforge=Forgiardente⟧.", "Un'altra anima persa in cerca di una guida, eh? Immagino tu voglia trovare uno scopo, il tuo scopo. L'ho visto mille volte: un altro eroe in cerca di lavoro.\n\nBe', oggi è il tuo giorno fortunato, amico. Hogral ha la cura per il tuo male.\n\nEcco cosa fai: prendi questa strada fino a ⟦Ironforge=Forgiardente⟧ e raggiungi la Forlorn Cavern. Lì, trova la gilda dei ladri e parla con Hulfdan Blackbeard. Ti metterà sulla via della salvezza.", nil, "Così ti credi una vera canaglia? Destinat<o/a> a essere <uno/una> dei pochi eletti di Blackbeard, un ufficiale dell'Hidden Circle?\n\nSolo un furfante buono a nulla penserebbe così bene di sé.\n\nÈ proprio quello che cerchiamo! Benvenut<o/a> a bordo, {name}!", 0x7deeb917, 0xc16240a1, 0x238604cf, nil, 0x3b3483ab, "...m." },
  [2238] = { "Un semplice sotterfugio", "Trova Onin MacHammar nei pressi di Gnomeregan.", "Vedi, il re sta sventrando la cava per estrarne minerali e gemme. Più ricchezze di quante un nano dovrebbe vederne in dieci vite.\n\nL'Hidden Circle ha dei valori, {name}. Noi diamo valore alle cose di valore. Capisci?\n\nOra, noi pensiamo che il re dovrebbe spartire un po' di quel bottino, ma non vogliamo che il vecchio «Stinkbeard» sappia che lo sta spartendo... se capisci cosa intendo.\n\nAbbiamo bisogno che tu parli con Onin MacHammar laggiù, vicino a Gnomeregan, e che riporti un rapporto. Quel nano furbo si è nascosto tra i lebbrosi. Fa' attenzione.", nil, "Ssst! Abbassa la voce, pezzo di idiota. Ci sentiranno.", 0xc34a099a, 0xba2a3a79, 0xad153087, nil, 0xab2bb692, "...m." },
  [2239] = { "⟦Onin's Report=Rapporto di Onin⟧", "Riporta il ⟦Onin's Report=Rapporto di Onin⟧ a Hulfdan, a ⟦Ironforge=Forgiardente⟧.", "La cava? Già, vedo quei mostruosi carri armati a vapore corazzati passare da questo posto quasi ogni giorno.\n\nI miei contatti a est mi dicono che il carro parte da ⟦Ironforge=Forgiardente⟧, fa un carico alla ⟦Gol'Bolar Quarry=Cava di Gol'Bolar⟧, si ferma a Kharanos per fare rifornimento e poi, per qualche dannato motivo, fa il giro lungo passando da Gnomeregan, prima di arrivare a ⟦Ironforge=Forgiardente⟧ per scaricare la spedizione.\n\nÈ tutto nel rapporto, {race}. Portalo a Hulfdan, così potrà pianificare la prossima mossa.", "Ti è piaciuto il fetore degli gnomi lebbrosi? Lo chiedo solo perché hai un sorriso da matto stampato in faccia.\n\nChe notizie porti da Onin?", "Il giro lungo? Per la mia barba!\n\nHai fatto un buon lavoro, {name}. Prendi questo pugnale e vattene. Il Circolo ti chiamerà di nuovo quando il passo tre sarà pronto per essere messo in atto.\n\nQual è il passo tre? Viene subito dopo il passo due: io che ti pianto lo stivale nel didietro.\n\nInteressat<o/a>?", 0xfee6746a, 0xb2b73a1a, 0x6d453b17, 0x7416d656, 0x6c9c93b3, "....." },
  [2240] = { "La camera nascosta", "Leggi il diario di Baelog, esplora la camera nascosta, poi fai rapporto al prospettore Stormpike.", "E ora, il compito che ci attende.\n\nC'è una camera segreta, la Chamber of Khaz'mul, che va esplorata. Il problema è che la camera si trova dietro un'enorme porta sbarrata! Per fortuna io so come aprirla.\n\nHo descritto tutto nel mio diario, qui sul tavolo. Io e il mio gruppo siamo bloccati qui per ora... quindi tu, {name}, devi trovare la Chamber of Khaz'mul per noi!\n\nLeggi il mio diario, esplora la camera, poi fai rapporto al prospettore Stormpike alla ⟦Explorers' League=Lega degli Esploratori⟧ di ⟦Ironforge=Forgiardente⟧.", "Hai qualcosa da riferire?", "Hai visto la Chamber of Khaz'mul? Straordinario! Baelog era sicuro che esistesse, ma devo ammettere che avevo i miei dubbi.\n\nGrazie, {name}. Con un po' di fortuna la tua scoperta spingerà i nostri capi a rinnovare gli sforzi per riconquistare Uldaman. E se mai tornerà sotto il controllo di ⟦Ironforge=Forgiardente⟧, i segreti della Chamber of Khaz'mul saranno nostri!", 0x715ec1d2, 0x426bb2d5, 0xd19acc6b, 0x0c101615, 0x1bbdd389, "....." },
  [2241] = { "La mela cade", "Porta la ⟦Jannok's Rose=Rosa di Jannok⟧ a Syurna, a Darnassus.", "Dicono che sono «cotto», qualunque cosa significhi.\n\nCerto, passo ogni momento da sveglio a pensare a Syurna. Certo, casa mia è piena di quadri e disegni di Syurna. Certo, spesso passo giorni senza mangiare, dormire o bere, mentre mi struggo per l'amore che avremmo potuto avere. È così sbagliato?\n\nE ora non vuole vedermi! ME! Ho provato a mandarle dei messaggi, ma non parla nemmeno con nessuno che non sia un ladro.\n\nPotresti consegnarle questo fiore? Non dimenticare di dirle che è da parte di Jannok.", "Oh, ma che meraviglia. Hai portato i fiori per il tuo stesso funerale.", "Se avessi conservato ogni fiore che quell'idiota di Jannok mi ha mandato, avrei avuto abbastanza per aprire un negozio. Comunque, sembra che l'ultimo messaggero di Jannok possa rivelarsi utile.\n\nTi interessa un po' di lavoro, {class}?", 0x1e34b4e5, 0x539618ee, 0xb5594b87, 0x9279e6d4, 0x640f88b7, "....." },
  [2242] = { "Il destino chiama", "Trova Sethir the Ancient e riporta a Syurna tutti gli indizi che scopri.", "Crediamo che esista un essere in grado di aiutarci a capire cosa sta succedendo alle foreste di Teldrassil. Purtroppo, convincere quella creatura a collaborare si è rivelato disastroso.\n\nSi nasconde su un ramo ai margini dell'Oracle Glade. Tutti quelli che finora si sono avvicinati al satiro, con la forza o con la diplomazia, hanno trovato la rovina. Forse la furtività è la risposta, {name}.\n\nScopri cosa porta con sé Sethir the Ancient nelle sue sacche e torna a riferirmelo.", "Hai qualcosa da riferire su Sethir the Ancient, {name}?", "Sono brutte notizie, {name}. Sembra che il morbo che ha colpito le foreste e i fiumi di ⟦Darkshore=Rivafosca⟧ abbia cominciato a contaminare la nostra casa.\n\nCi hai servito bene, ma qui non c'è altro che tu possa fare. Prendi questa lama come ricompensa per il tuo servizio a Teldrassil.", 0x8c35f2ae, 0xe9faceef, 0xccf34b01, 0x274bca56, 0x1dda5b8b, "....." },
  [2258] = { "Reagenti delle ⟦Badlands=Maleterre⟧", "Porta 5 Stomaco di Condor, 10 Zanna di Coyote delle Rupi e 5 Scheggia Elementale di Roccia a Jarkal Mossmeld a Kargath, nelle ⟦Badlands=Maleterre⟧.", "{name}, mi farebbe comodo il tuo aiuto, se te la senti. Sono un alchimista di una certa fama, e cerco aiuto per procurarmi alcuni reagenti che si trovano nelle ⟦Badlands=Maleterre⟧.\n\nPer rifornire le mie scorte mi servono: cinque stomaci di condor, dieci zanne di coyote delle rupi e cinque schegge elementali di roccia. Ovviamente puoi prenderli dalle bestiacce stesse; se non sei tipo da combattere, trova degli amici che lo siano.\n\nProcurami queste cose e ci guadagnerai qualche moneta. Che vuoi fare?", "Hai già preso le cose che mi servono? Non ti pagherò finché non mi porti quei reagenti.", "Ah, ben fatto! Queste dovrebbero bastarmi almeno per un po'. Ecco la tua paga, come promesso.\n\nSe ti interessa, ci sono altri reagenti che mi servirebbero. Questi però si trovano solo nelle profondità degli scavi di Uldaman. Non sarà facile procurarli, ma ne varrà la pena, se vorrai aiutarmi di nuovo.\n\nMagari con qualcosa di più di qualche moneta luccicante, eh?", 0xaca0069d, 0xd99e4eb2, 0x58ee6bec, 0x5be9782d, 0xdcc1d162, "....." },
  [2259] = { nil, "Contatta Erion Shadewhisper a Darnassus.", "Non preoccuparti, {name}, non ti sto mandando da Syurna. Erion richiede la tua presenza all'⟦Cenarion Enclave=Enclave Cenariana⟧. Affrettati!", nil, "È tempo di allargare i tuoi orizzonti, {race}: il mondo ti aspetta.", 0x372c4f19, 0x1eb27f12, 0x7bffcd48, nil, 0x1d5a0e27, "e..m." },
  [2260] = { "La richiesta di Erion", "Raggiungi ⟦Stormwind City=Roccavento⟧ e chiedi consiglio a Renzik \"The Shiv\".", "La voce delle tue imprese si è diffusa ovunque, {name}. Tanto che i servizi segreti di ⟦Stormwind=Roccavento⟧ hanno chiesto di te per nome.\n\nIl viaggio è faticoso e non privo di pericoli, ma l'occasione di addestrarsi con l'⟦SI:7=IR:7⟧ non va presa alla leggera.\n\nTi aspetta un mondo nuovo, {name}. Raggiungi Old Town, a ⟦Stormwind=Roccavento⟧, e parla con Renzik \"The Shiv\" al quartier generale dell'⟦SI:7=IR:7⟧.", nil, "Hai risposto alla chiamata dell'IR:7, {name}, e hai viaggiato da terre lontane per unirti alle nostre file; tuttavia, hai ancora molto da imparare.", 0x01bdb2d2, 0x370fd4f0, 0x6d9f7c62, nil, 0xd5283d8b, "...m." },
  [2281] = { "Appuntamento a ⟦Redridge=Crestarossa⟧", "Avventurati fino a ⟦Lakeshire=Borgolago⟧, nelle ⟦Redridge Mountains=Montagne Crestarossa⟧, e parla con Lucius.", "Mandarti sul campo adesso sarebbe un suicidio. A Renzik non serve un altro ladro morto sulla coscienza. Ma non agitarti, {name}: Renzik ti metterà al passo.\n\nRaggiungi le ⟦Redridge Mountains=Montagne Crestarossa⟧ e parla con un collaboratore dell'⟦SI:7=IR:7⟧ di nome Lucius. Lo troverai a bighellonare sui moli di ⟦Lakeshire=Borgolago⟧ con gli altri fannulloni loschi.", nil, "Ah, hai le dita un po' grosse, eh? Non preoccuparti, {name}, ho trasformato ladruncoli più inutili di te in ladri esperti.", 0x1179ca1d, 0x8ce09cc7, 0xde207c62, nil, 0xf1b6dc03, "...m." },
  [2282] = { "⟦Alther's Mill=Segheria di Alther⟧", "Apri il Lucius's Lockbox, recupera l'⟦Token of Thievery=Emblema del Ladro⟧ e riportalo a Lucius, a ⟦Lakeshire=Borgolago⟧.", "Addestriamo ladri qui da anni! Del resto, non tutte le canaglie nascono con la grazia e la finezza del vecchio Lucius.\n\nPiù su, oltre la strada, troverai la ⟦Alther's Mill=Segheria di Alther⟧. Lassù ho un forziere con dentro una cosa importante. Va' a prendermela! Riporta quell'emblema e riceverai il tuo ⟦Certificate of Thievery=Attestato di Ladro⟧!", "Ho dimenticato di dirti degli orchi?\n\nHo sentito che ficcano il naso lassù, vicino alla segheria.", "L'hai aperto, eh? Bel lavoro, {name}.\n\nSe adesso muori, possiamo stare tranquilli sapendo che è stato per la tua stupidità e non per inesperienza.", 0xe7ba8f99, 0x26100448, 0xb5640ee8, 0xe82c551e, 0x0465ee25, "....." },
  [2298] = { "Un'estorsione reale", "Raggiungi ⟦Stormwind=Roccavento⟧ e cerca Renzik \"The Shiv\".", "Allora, eravamo lì lì per cominciare a pianificare la fase III, quando un paio di zucconi di Magni piombano qua dentro a blaterare di un qualche colpo e ad arrestare alcuni dell'Hidden Circle.\n\nBeh, nessuno mette i ferri al vecchio Blackbeard! La discussione s'è fatta pesante e animata e, chissà come, è saltato fuori il tuo nome!\n\nIl mio consiglio? Prendi il primo grifone da ⟦Ironforge=Forgiardente⟧ e vai a ⟦Stormwind=Roccavento⟧. Raggiungi Old Town e lì parla con un mio vecchio amico, Renzik \"The Shiv\".", nil, "Fa sempre piacere avere uno dei ladri di Hulfdan tra le nostre file!", 0xd942bb73, 0xbbb8bc4a, 0x640cf402, nil, 0x4704075e, "...m." },
  [2299] = { "Da Hulfdan!", "Raggiungi ⟦Ironforge=Forgiardente⟧ e parla con Hulfdan Blackbeard.", "Dove sei finit<o/a>, {name}? Hulfdan ti sta cercando dappertutto. Pensavamo che il re ti avesse messo ai ferri.\n\nVai a ⟦Ironforge=Forgiardente⟧ il prima possibile e parla con Hulfdan!", nil, "Abbassa la voce, {name}, le guardie potrebbero sentirti.", 0x612d5545, 0x995810c1, 0x7e2c7b3a, nil, 0x03d4865c, "...m." },
  [2300] = { "⟦SI:7=IR:7⟧", "Raggiungi ⟦Stormwind=Roccavento⟧ e cerca Renzik \"The Shiv\".", "Renzik ti cercava, recluta.\n\nAl posto tuo non farei aspettare il vice di Mathias.", nil, "Sei pront<o/a> a metterti al lavoro o ti serve un pisolino prima di cominciare?", 0x0b3264b7, 0xbbb8bc4a, 0xf9063657, nil, 0x6f885d66, "...m." },
  [2358] = { "⟦Horns of Nez'ra=Corna di Nez'ra⟧", "Riporta le ⟦Horns of Nez'ra=Corna di Nez'ra⟧ ad Arantir's Shadow a ⟦Lakeshire=Borgolago⟧.", "Molti anni fa, le ⟦Horns of Nez'ra=Corna di Nez'ra⟧ furono rubate dal Maniero dei ⟦Ravenholdt=Corvolesto⟧. Le ho cercate attraverso continenti e oceani, solo per scoprire che queste bestie insignificanti le avevano sempre avute in loro possesso.\n\nUccidi ogni orco ⟦Blackrock=Roccianera⟧ che incontri finché non avrai recuperato le ⟦Horns of Nez'ra=Corna di Nez'ra⟧. Se le recuperi, trovami a ⟦Lakeshire=Borgolago⟧.\n\nFallo per me e il tuo nome sarà noto ai ⟦Ravenholdt=Corvolesto⟧, {name}.", "Hai le corna del principe demoniaco?", "Negare il manufatto a ⟦Ravenholdt=Corvolesto⟧ sarebbe come negare la propria stessa esistenza. Ben fatto, <ladro/ladra>. Un giorno potresti camminare tra gli assassini di ⟦Ravenholdt=Corvolesto⟧.\n\nDa giovane, quando andavo all'avventura a ⟦Darkshore=Rivafosca⟧, scoprii un tè che ripristina l'energia in combattimento. Mi è stato utile per tutti questi anni e ora ti passo un assaggio di Tè di Sboccialesto. Bevine quando ti senti senza forze, {name}, e combatti di nuovo con vigore!", 0xd52ec603, 0x3b5ab7d3, 0x4584825e, 0xe35c152d, 0x1f0b2efd, "....." },
  [2359] = { "La torre di Klaven", "Ruba la Defias Tower Key, irrompi nella torre dei Defias e scopri il contenuto del forziere di ⟦Duskwood=Boscovespro⟧. Porta le informazioni che trovi a Mathias Shaw, a ⟦Stormwind=Roccavento⟧. Leggi il ⟦Kearnen's Journal=Diario di Kearnen⟧ per saperne di più sulla torre.", "Sono settimane che sorveglio questa torre, {name}. Di recente è arrivato un grosso carico da ⟦Duskwood=Boscovespro⟧, e con esso quelle guardie.\n\nCosa sono? Ne so quanto te. Una cosa però te la posso dire: non sono umani.\n\nComunque, nel carico c'era un forziere, ed è quello che immagino stiano sorvegliando quegli abomini. Lo zombi con gli spuntoni ha una chiave che ci serve.\n\nPrendi quella chiave, entra nella torre e scopri cosa c'è in quel forziere. Porta ciò che trovi a Mathias.", "Notizie dall'agente Kearnen?", "Questo spiegherebbe i droni dei Defias che tu e Kearnen avete visto fuori dalla torre, {name}. Spiegherebbe anche il coinvolgimento della S.P.R. & Co. con i Defias e gli strani carichi in partenza da ⟦Duskwood=Boscovespro⟧.\n\nSecondo questo libro, i troll Zanzil di Rovotorto hanno scoperto un modo per risvegliare i morti con le pozioni... o, per essere precisi, con il veleno.\n\nNon sarai di nessuna utilità all'⟦SI:7=IR:7⟧ senza una solida conoscenza dei veleni, {name}, soprattutto ora che abbiamo a portata di mano la ricetta per creare la non morte.", 0x7a0fe55b, 0x84c572ed, 0xffbbc189, 0x6bdfdca0, 0xea54e6be, "....." },
  [2360] = { "Mathias e i Defias", "Raggiungi le ⟦Westfall=Marche Occidentali⟧ e trova l'agente Kearnen per ricevere il rapporto.", "Appena in tempo, {name}. Le ricognizioni dell'⟦SI:7=IR:7⟧ segnalano un'attività insolitamente intensa dei Defias nelle ⟦Westfall=Marche Occidentali⟧.\n\nPare che i Defias si siano impadroniti di una torre di guardia abbandonata dell'⟦Alliance=Alleanza⟧ a sud-est di ⟦Sentinel Hill=Guardiacolle⟧ e la stiano usando come base operativa per contrabbandare merci dalla via di rifornimento di ⟦Redridge=Crestarossa⟧.\n\nVa' nelle ⟦Westfall=Marche Occidentali⟧ e contatta l'agente Kearnen per il rapporto. La troverai nascosta vicino alla torre.\n\n...e, {name}, se dovessi essere scopert<o/a>, l'⟦SI:7=IR:7⟧ negherà di sapere alcunché della tua esistenza.", nil, "Mathias ha finalmente mandato un altro agente a darmi man forte, eh? Be', spero che sia pronto a sentire brutte notizie.", 0x105ec7f9, 0x8fda0905, 0x763fbd75, nil, 0x167ae4df, "...m." },
  [2378] = { "Alla ricerca della Shattered Hand", "Raggiungi Orgrimmar e parla con Shenthul al Cleft of Shadow.", "Hai servito bene gli ⟦Deathstalkers=Inseguitori della Morte⟧, {name}, ma forse è tempo che tu ti spinga oltre. Hai mostrato attitudine per la furtività e l'inganno, ma hai ancora bisogno di molto addestramento.\n\nGli ⟦Deathstalkers=Inseguitori della Morte⟧ hanno alleati nella Shattered Hand. Cerca coloro che ci aiuterebbero: trova Shenthul a Orgrimmar.", nil, "Quindi sei tu ciò che i nostri potenti alleati hanno mandato a Shenthul? Che delusione...", 0x4edc9e9f, 0xb842824b, 0x66a5c788, nil, 0x38cd9abf, "...m." },
  [2379] = { nil, "Parla con Zando'zan al Cleft of Shadow.", "La tua sola determinazione non basta a superare gli ostacoli che ci attendono.\n\nParla con Zando'zan per iniziare il tuo addestramento come agente della Shattered Hand.\n\nSolo quando avrai padroneggiato le arti della furtività e del furto potrai compiere il passo successivo verso il tuo destino.", nil, "Forse Zando'zan si sbagliava. Zando'zan chiede scusa.", 0xb5f8d527, 0x72e5b430, 0x5267d5d0, nil, 0x1bd8647f, "e..m." },
  [2380] = { "A Orgrimmar!", "Parla con Shenthul al Cleft of Shadow, a Orgrimmar.", "Non sei <un/una> <maestro/maestra> di furtività e inganno, ma tutto questo può cambiare e cambierà. Evidentemente hai impressionato i capi con le tue misere abilità, visto che il grande Shenthul ha chiesto di te per nome.\n\nPrendi la strada a nord di qui fino a Orgrimmar e parla con Shenthul nel Cleft of Shadow.", nil, "È importante che la Shattered Hand resti vigile di fronte ai cambiamenti che Thrall vuole portare nell'⟦Horde=Orda⟧. Il nostro numero da solo non basterà a rovesciare il suo dominio: bisogna padroneggiare la furtività e l'inganno.", 0x2374baca, 0x53b81ad0, 0x7f04c7de, nil, 0x065d936e, "...m." },
  [2381] = { "Derubare i predoni", "Riporta il ⟦Southsea Treasure=Tesoro dei Mari del Sud⟧ a Wrenix the Wretched, a ⟦Ratchet=Porto Paranco⟧. Non dimenticare di prendere un E.C.A.C. e gli ⟦Thieves' Tools=Strumenti dei Ladri⟧ dal Gizmotronic Apparatus di Wrenix. Ti serviranno entrambi per portare a termine la missione.\n\nSe vieni <attaccato/attaccata> da pappagalli insolitamente ostili, usa l'E.C.A.C.!", "Non voglio spaventarti, {name}, ma gli ultimi cinque ladri che ho mandato a rubare il tesoro dei Mari del Sud mi sono tornati a pezzi.\n\nA sud, lungo la costa, troverai la Tide Razor, la nave dei filibustieri dei Mari del Sud. Nascosto nella stiva c'è il bottino: il tesoro dei Mari del Sud. Sul secondo ponte della nave c'è il covo dei pirati, il posto dove addestrano tutti i loro ladri.\n\nSali a bordo, ruba il tesoro e riportamelo. Usa il covo dei pirati se hai bisogno di fare pratica come ladro, ma sta' attent<o/a>!", "Be', almeno hai ancora tutte le parti del corpo. Hai trovato il tesoro?", "Incredibile! Inverosimile! Semplicemente fantastico! Hai talento, {name}. O questo, o sei la persona più fortunata del mondo!\n\nEcco la tua parte del bottino. Sono sicuro che sapresti usare questa roba meglio di me.", 0xee0557f2, 0x3ff88d8f, 0xbebe5cc4, 0x738c0a5e, 0x11243ac4, ".....", nil, nil, nil, nil, 0xe028f305 },
  [2382] = { "Wrenix di ⟦Ratchet=Porto Paranco⟧", "Raggiungi ⟦Ratchet=Porto Paranco⟧ e parla con Wrenix the Wretched.", "Zando'zan l'ha visto! Sì, il giorno arriva! La morte di Thrall... il pugnale nella schiena, il veleno che gli scorre in ogni vena... Zando'zan ha detto troppo.\n\n{name}! Zando'zan ha un compito per {name}! {name} deve andare a ⟦Ratchet=Porto Paranco⟧, a est di ⟦Crossroads=Crocevia⟧, e parlare con Wrenix the Wretched. Va'!", nil, "Un altro? Gli ultimi cinque che quel troll pazzo mi ha mandato sono finiti in pasto agli squali. Speriamo che a te vada un po' meglio, eh?", 0x05456afd, 0x578f4c54, 0xc9799e26, nil, 0xa433399d, "...m." },
  [2383] = { "⟦Simple Parchment=Cartapecora Semplice⟧", "Leggi la ⟦Simple Parchment=Cartapecora Semplice⟧ e parla con Frang nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Ah, mentre eri via è arrivata una cartapecora per te, {name}.\n\nLeggila quando hai tempo. Se non sbaglio, viene dall'istruttore dei guerrieri Frang. Vuole parlarti quando sarai pront<o/a>. Lo troverai fuori dall'Antro del Tirocinio, al riparo all'ombra.", "Cos'hai lì? Una cartapecora? Spero che tu non sia <uno/una> studios<o/a>...", "Ah, questa è la mia cartapecora. Avevo sentito che saresti venut<o/a> nella Valle, {name}. Mi fa piacere vedere che ce l'hai fatta: speriamo che tu sopravviva alle prove che ti aspettano. Come ho detto, man mano che diventi più potente, vieni da me: farò il possibile per addestrarti nelle vie del {class}.\n\nBuona fortuna, {name}, e torna da me quando ti senti pront<o/a>.", 0x1d01cad6, 0x159b5995, 0xb9d4e50a, 0xbf9315ae, 0x818eae1e, "....." },
  [2398] = { "I nani perduti", "Trova Baelog a Uldaman.", "Gli scavi di Uldaman non sono sempre stati invasi. Noi nani di ⟦Ironforge=Forgiardente⟧ controllavamo la zona, ma... era prima che arrivassero i trogg. Arrivarono così in fretta e in tal numero che nemmeno la forza dei nani riuscì a fermarli!\n\nAnzi, il loro attacco fu così improvviso che temo che alcuni dei nostri siano rimasti intrappolati dietro le linee nemiche.\n\nIl mio amico Baelog ha guidato un piccolo gruppo di nani nel profondo degli scavi poco prima che arrivassero i trogg. Se lui e i suoi compagni sono vivi, voglio che tu li trovi.", nil, "Era ora che arrivassi! Stavo per perdere una scommessa con Olaf!\n\nHa scommesso che la barba gli sarebbe arrivata alle ginocchia prima di vedere di nuovo <un/una> {race} in carne e ossa. Be', eccoti qui, e come vedi alla barba di Olaf mancano ancora parecchi centimetri.\n\nGrazie, {name}. Dividerò la vincita con te.", 0x826b7a46, 0x194d79a7, 0x1cc327cb, nil, 0xc693cc2f, "...m." },
  [2399] = { "Le fronde germogliate", nil, nil, nil, "Le fronde che Denalan ha piantato nel suo giardino sono germogliate e cresciute. Fremono, impazienti di essere raccolte...", 0xd9520005, nil, nil, nil, 0x87fc0eaa, ".mmm." },
  [2418] = { "Pietre del potere", "Porta 8 Pietra del Potere di Dentrium e 8 Pietra del Potere di An'Alleum a Rigglefuzz nelle ⟦Badlands=Maleterre⟧.", "Tempo fa ho avuto un incidente con i nani Forgiascura. Mi hanno portato alla ⟦Angor Fortress=Fortezza di Angor⟧ per studiare due tipi di strane pietre provenienti da Uldaman. Ho scoperto che, se trattate nel modo giusto, le pietre erano fonti di energia stabili e durature. È incredibile cosa si trova in quel vecchio sito di scavo!\n\nComunque, dopo che ho rivelato loro il segreto delle pietre, mi hanno cacciato dalla ⟦Angor Fortress=Fortezza di Angor⟧ e si sono messi a scavare a Uldaman per trovarne altre.\n\nVoglio quelle pietre per me! Portami tutti e due i tipi e ti pagherò profumatamente!", "Hai le pietre del potere, {name}? Ho un roditore robotico che ha bisogno di una fonte di energia...", "Fantastico, ne hai trovate! Grazie mille, {name}. Sei <il/la> {race} più affidabile che abbia mai conosciuto!\n\nNon vedo l'ora di provarle su alcuni congegni che sto mettendo a punto. Scommetto che, nelle giuste condizioni, i congegni alimentati con queste pietre continueranno ad andare, e andare, e andare...", 0x2a8fd07d, 0xf6808489, 0x69dbb206, 0x8950568a, 0xa4af47c3, "....." },
  [2438] = { "L'⟦Emerald Dreamcatcher=Acchiappasogni di Smeraldo⟧", "Porta l'⟦Emerald Dreamcatcher=Acchiappasogni di Smeraldo⟧ a Tallonkai Swiftroot a Dolanaar.", "Tempo fa Gaerolas Talvethen, il custode dei druidi nell'⟦Ban'ethil Barrow Den=Eremo di Ban'ethil⟧, mi donò un Acchiappasogni di Smeraldo. Questo potente amuleto è in grado di attingere energia dal ⟦Emerald Dream=Sogno di Smeraldo⟧, e porta fortuna a chi lo possiede.\n\nPurtroppo non sono riuscito a recuperarlo dal mio cassettone a ⟦Starbreeze Village=Brezzastella⟧... Un tempo ⟦Starbreeze Village=Brezzastella⟧ era un luogo tranquillo, ma ora è caduta preda della corruzione dei mezzorsi che vi abitano.\n\nForse saresti <disposto/disposta> a recuperare il mio acchiappasogni, {class}?", "Ti prego, fa' presto. Posso solo sperare che i mezzorsi non abbiano danneggiato il mio Acchiappasogni di Smeraldo.\n\nL'hai già recuperato, {name}?", "Il mio Acchiappasogni di Smeraldo è molto importante per me. È un dono concesso a pochi. Grazie per avermelo riportato, {name}.", 0x15f1c399, 0x52a2d29e, 0xfe33a929, 0x164e94f7, 0x1efbac0d, "....." },
  [2458] = { "Sotto copertura", "Raggiungi la torre della S.P.R. & Co., a nord della ⟦Sludge Fen=Palude Fangosa⟧, e contatta l'agente infiltrato della Shattered Hand, il ⟦Taskmaster Fizzule=Coordinatore Fizzule⟧.\n\nQuando la torre è in vista, usa lo ⟦Flare Gun=Spararazzi⟧ per segnalare il tuo arrivo al ⟦Taskmaster Fizzule=Coordinatore Fizzule⟧. Spara DUE razzi, poi avvicinati al ⟦Taskmaster Fizzule=Coordinatore Fizzule⟧ ed esegui lo Shattered /Salute.\n\nQueste azioni vanno eseguite nell'ordine corretto, perché Fizzule attacca ed elimina chiunque non riconosca.", "La ⟦Venture Company=S.P.R. & Co.⟧... Forse ne hai sentito parlare?\n\nPer un anno abbiamo lavorato per infiltrare un agente nel profondo dei loro ranghi. Con molto impegno e un'attenta pianificazione, ci siamo riusciti.\n\nDi recente ci è giunta voce che la ⟦Venture Company=S.P.R. & Co.⟧ sta preparando qualcosa in grande stile. Va' a nord della ⟦Sludge Fen=Palude Fangosa⟧, alla torre della ⟦Venture Company=S.P.R. & Co.⟧, e contatta il nostro agente infiltrato, il ⟦Taskmaster Fizzule=Coordinatore Fizzule⟧.\n\nQuando trovi la torre, usa questo spararazzi, poi avvicinati a Fizzule e mostragli il saluto della Shattered Hand.", nil, "Fa piacere vedere un altro agente della Shattered Hand da queste parti, però il razzo forse era un po' esagerato!\n\nLa prossima volta che devi parlarmi, soffia due volte in questo fischietto e saprò che sei dei nostri.", 0x379ff3f0, 0x8c974479, 0x9977ca74, nil, 0xc03a9821, "...m." },
  [2459] = { nil, "Tallonkai Swiftroot di Dolanaar vuole che tu uccida 7 Gnarlpine Mystic e trovi il gioiello scomparso.", "Lo smeraldo... È scomparso! Il mio acchiappasogni è stato danneggiato!\n\nC'è una banda di mistici ⟦Gnarlpine=Mordipigna⟧ a nord di Starbreeze. Ho sentito dire che il loro capo, Ferocitas the Dream Eater, porta una collana che di notte risplende di verde. Ora che vedo il mio acchiappasogni, sono sicuro che sia stato lui a rubare il mio smeraldo... Non capirebbe mai che il suo potere per lui è inutile.\n\nTrova il gioiello scomparso, {name}. E, già che ci sei, elimina anche un po' di quei mistici corrotti.", "Ferocitas e i mistici ⟦Gnarlpine=Mordipigna⟧ devono restituire ciò che è mio. Ti prego, recupera lo smeraldo così che io possa riparare il mio acchiappasogni di smeraldo.", "Ora posso riparare il mio acchiappasogni. Grazie, {name}.", 0x236ef724, 0x4c50de14, 0x837c9efe, 0x9c2bf253, 0x00d792cf, "e...." },
  [2460] = { "Lo Shattered Salute", "Esegui lo Shattered Salute davanti a Shenthul.", "Come <ladro/ladra> della Shattered Hand, è indispensabile che tu impari lo Shattered Salute. È l'unico modo per riconoscere davvero un altro membro della Hand.\n\nGuarda, impara, ripeti.", "Esercitati!", "Ben fatto, {name}. Ora sei pront<o/a> a proseguire.", 0xe29bc468, 0xbc1b393c, 0x21bdbb05, 0xa5a697be, 0xc8d80fd4, "....." },
  [2478] = { "Missione: possibile ma non probabile", "Ruba la Silixiz's Tower Key al caposquadra Silixiz, poi uccidi due Mutated Venture Co. Drone, due Venture Co. Patroller e due Venture Co. Lookout.\n\nAssassina il gran caposquadra Gallywix e prendi la sua testa, poi scassina il forziere di Gallywix e ruba la ⟦Cache of Zanzil's Altered Mixture=Cassa di Mistura di Zanzil Alterata⟧. Porta la Cassa e la ⟦Gallywix's Head=Testa di Gallywix⟧ a Shenthul, a Orgrimmar, per ulteriori istruzioni.", "Dovrai rubare la chiave della torre al caposquadra Silixiz, {name}. Una volta che l'avrai, tienila: potrebbe servirmi più avanti.\n\nRicorda, il veleno ha indebolito tutti in questa torre. Usa le tue abilità per seminare caos e distruzione tra chi ci vive. Uccidili tutti, senza pietà!\n\nQuando tutto là dentro sarà un mucchio insanguinato, scassina il forziere di Gallywix e ruba la cassa di mistura di Zanzil che contiene. Porta sia la testa di Gallywix sia la mistura a Shenthul, a Orgrimmar.", "Cos'hai da riferire, {name}?", "Povero Fizzule, era un buon agente, uno dei migliori. Ahimè, è il prezzo da pagare, {name}. Essere un agente sul campo della Shattered Hand è un lavoro pericoloso.\n\nHai fatto bene il tuo dovere, {class}. Sarebbe un peccato se non sopravvivessi per servirci ancora.", 0x889d9a10, 0x323252b6, 0xc695e02b, 0xd8f33c29, 0x2c36763c, "....." },
  [2479] = { "L'aiuto di Hinott", "Raggiungi il ⟦Tarren Mill=Mulino di Tarren⟧, nelle ⟦Hillsbrad Foothills=Alture di Colletorto⟧, e consegna il campione di ⟦Zanzil's Mixture=Fiala della Mistura di Zanzil⟧ a Serge Hinott.\n\nPer arrivare al ⟦Tarren Mill=Mulino di Tarren⟧, prendi lo zeppelin per ⟦Undercity=Sepulcra⟧ e segui la strada verso sud attraverso ⟦Silverpine=Pinargento⟧, in direzione di ⟦Hillsbrad=Colletorto⟧. Segui i cartelli!", "Porta un campione della mistura a Serge Hinott, al ⟦Tarren Mill=Mulino di Tarren⟧.\n\nSe qualcuno può curarti, quello è Serge. Sopravvivi abbastanza a lungo e Serge ti insegnerà a creare e usare i veleni.", "Che cos'è questo???", "Hai un pallore delizioso, {class}. E cos'è quell'odore nauseabondo che emani? Devo saperlo!", 0x59895e49, 0xe1eb607d, 0x1bcf7a9f, 0x1de2dddb, 0x558ebfce, "....." },
  [2480] = { "L'aiuto di Hinott", "Aspetta che Serge Hinott completi la cura.", "Non ho mai visto risultati tanto prodigiosi da un veleno! Zanzil, dici? Mai sentito nominare, però devo complimentarmi con lui per aver creato questo intruglio.\n\nDunque, dovrei curarti da questo e poi insegnarti a usare il veleno?\n\nDammi qualche momento per esaminare la tossina, {name}.", nil, "La cura è pronta! Bevi questo antitossico e la follia strisciante si fermerà, però non potrò fare niente per l'odore.", 0x59895e49, 0xd6da9379, 0x9ead8b00, nil, 0x37216e45, "...m." },
  [2498] = { "Ritorno da Denalan", "Rellian Greenspyre vuole che tu parli con Denalan, al ⟦Lake Al'Ameth=Lago Al'ameth⟧.", "Mi è appena giunta notizia che Denalan, al ⟦Lake Al'Ameth=Lago Al'ameth⟧, ha scoperto quella che potrebbe essere la causa dei tumori che affliggono i timberling. Ti prego, va' a parlargli e digli che ti mando io.\n\nAffrettati, {name}: ha bisogno del nostro aiuto.", nil, "Ah, quindi Rellian ti ha mandato ad aiutarmi. Sono lieto che tu sia arrivat<o/a> così presto.\n\nHo scoperto qualcosa di davvero inquietante!", 0x86434b8b, 0x01cfe979, 0x16e96e4d, nil, 0xbdb97620, "...m." },
  [2499] = { nil, "Denalan, al ⟦Lake Al'Ameth=Lago Al'ameth⟧, vuole che tu prenda il ⟦Gargantuan Tumor=Tumore Gigantesco⟧ di Oakenscowl.", "In una grotta lungo la sponda meridionale del lago, un timberling di nome Oakenscowl sta diffondendo la corruzione a tutte le creature che vivono al ⟦Lake Al'Ameth=Lago Al'ameth⟧.\n\nNon ho osato avvicinarmi troppo, ma anche da lontano è evidente: Oakenscowl è avvelenato dal tumore più grande che abbia mai visto... lo definirei persino gigantesco.\n\n{name}, hai già fatto molto per aiutarmi, ma ti chiedo un ultimo compito. Dai la caccia a Oakenscowl e prendi il tumore: elimina questa fonte di corruzione dalla mia casa.", "Hai già trovato Oakenscowl, {race}?", "Sapevo che eri più che in grado di liberare il lago da quella bestia orribile.\n\nÈ una situazione angosciante: un tempo Oakenscowl era un grande capo tra i suoi simili... ma la corruzione non fa distinzione tra umili e nobili.\n\nLe dimensioni di questo tumore sono davvero inquietanti, ma devo studiarlo per saperne di più sulla malattia che affligge i timberling.\n\nGrazie, {name}.", 0xa9dba359, 0x0d86e120, 0x1f483fdc, 0x5c25b955, 0x92662c82, "e...." },
  [2500] = { "Reagenti delle ⟦Badlands=Maleterre⟧", "Procurati nelle ⟦Badlands=Maleterre⟧ i reagenti che servono a Ghak Healtouch, poi torna da lui a Thelsamar.", "{class}, vorrei avvalermi dei tuoi servigi. Sono un alchimista di una certa fama, e cerco aiuto per procurarmi alcuni reagenti che si trovano nelle ⟦Badlands=Maleterre⟧.\n\nPer rifornire le mie scorte mi servono: cinque stomaci di condor, dieci zanne di coyote delle rupi e cinque schegge elementali di roccia. Ovviamente puoi prenderli dalle bestiacce stesse; se non sei tipo da combattere, trova degli amici che lo siano.\n\nProcurami queste cose e ci guadagnerai qualche moneta.\n\nAllora, che ne dici?", "Hai già preso le cose che mi servono? Non ti pagherò finché non mi porti quei reagenti.", "Ah, ben fatto, {name}. Queste dovrebbero bastarmi almeno per un po'. Ecco la tua paga, come promesso.\n\nSe ti interessa, ci sono altri reagenti che mi servirebbero. Questi però si trovano solo nelle profondità degli scavi di Uldaman. Non sarà facile procurarli, ma ne varrà la pena, se vorrai aiutarmi di nuovo.\n\nMagari con qualcosa di più di qualche moneta luccicante, eh?", 0xaca0069d, 0xf4c53465, 0xe9758759, 0x5be9782d, 0xf953efd3, "....." },
  [2518] = { "Lacrime della luna", "La sacerdotessa A'moora, nel ⟦Temple of the Moon=Tempio della Luna⟧ a Darnassus, vuole che tu le porti la ⟦Silvery Spinnerets=Filatura Argentea⟧ di Lady Sathrah.", "Lady Sathrah un tempo era prediletta da Elune. Aggraziato e puro, il ragno tesseva i suoi fili d'argento al chiaro di luna, catturando la foschia della sera. La rugiada argentea aveva grandi poteri curativi ed era custodita qui nel tempio.\n\nMa di recente Sathrah è sprofondata nella follia. Ora sono minacciate anche le sue generazioni future.\n\nTrova Lady Sathrah, {name}, e poni fine alle sue sofferenze. Dimora lungo i confini settentrionali di Teldrassil, vicino al ⟦Wellspring Lake=Lago di Buonpozzo⟧. Raccogli la sua filatura argentea e riportala a me.", "Mi rammarico del compito che ti ho chiesto di svolgere, ma per Lady Sathrah non c'è più speranza.\n\nSperiamo di offrire a Elune il sacrificio della filatura. Con questo sacrificio Elune benedirà Sathrah, perché possa rinascere e trovare la pace.", "La foresta piange Lady Sathrah, ma era una cosa che andava fatta.\n\nGrazie, {name}.", 0x590caf7f, 0x6c622142, 0x20922da4, 0x35d5c5a2, 0x309445ea, "....." },
  [2519] = { "Il ⟦Temple of the Moon=Tempio della Luna⟧", "Sorella Aquinne vuole che tu parli con la sacerdotessa A'moora nel ⟦Temple of the Moon=Tempio della Luna⟧.", "Una creatura della foresta, un tempo grandiosa, ha bisogno di aiuto, {race}.\n\nC'è un compito difficile da portare a termine.\n\nTi prego, cerca la sacerdotessa A'moora: ti spiegherà tutto. La troverai a sud-est di qui, all'interno del ⟦Temple of the Moon=Tempio della Luna⟧.", nil, "Allora, ti ha mandato sorella Aquinne?", 0xbf995b33, 0xfccb6f52, 0xb532fd45, nil, 0x4f3a53a8, "...m." },
  [2520] = { "⟦Sathrah's Sacrifice=Sacrificio di Sathrah⟧", "La sacerdotessa A'moora vuole che tu deponga la filatura argentea di Lady Sathrah presso la fontana all'interno del tempio, e che poi torni da lei.", "Ora devi portare a termine il compito che ti è stato affidato. Prendi la filatura e offri a Elune il sacrificio di Lady Sathrah; concedi al grande ragno il riposo eterno.\n\nAll'interno di questo tempio, trova la fontana centrale. È lì che potrai lasciare il sacrificio. Le acque sacre purificheranno e laveranno via la corruzione che ha fatto impazzire Sathrah.\n\nQuando avrai finito, torna da me.", "Hai deposto il sacrificio presso la fontana, {name}?", "La perdita di Lady Sathrah è dolorosa, ma solo così potrà rinascere con uno spirito rinnovato.\n\nChe Elune accolga di buon grado il sacrificio che le hai offerto.", 0x5a3cb37c, 0x6736b09f, 0x7b40ee6c, 0xf5b1c4b7, 0xbd5ac00f, "....." },
  [2541] = { "Il Druido dormiente", "Porta un ⟦Shaman Voodoo Charm=Talismano Sciamanico Vudù⟧ a Oben Rageclaw all'⟦Ban'ethil Barrow Den=Eremo di Ban'ethil⟧.", "Gli sciamani ⟦Gnarlpine=Mordipigna⟧ che abitano questo luogo hanno scoperto un modo per separare lo spirito di un druido addormentato dal suo corpo fisico. I mezzorsi hanno animato il mio corpo e lo usano per attaccare chiunque cerchi di esplorare l'⟦Ban'ethil Barrow Den=Eremo di Ban'ethil⟧. Ora sono intrappolato nel ⟦Emerald Dream=Sogno di Smeraldo⟧, impotente a fermarli.\n\nDevi aiutarmi. Gli sciamani ⟦Gnarlpine=Mordipigna⟧ portano uno strano talismano che usano per compiere questo rituale, e vorrei esaminarlo. Ti prego, {name}, portamene uno.", "Se potessi esaminare il talismano, forse riuscirei a capire come spezzare l'incantesimo. Ne hai trovato uno?", "Grazie, {name}.\n\nChe strano ninnolo è questo... Sento l'aura malvagia che emana; è un incantesimo molto potente.", 0xf13c0bd8, 0xb6182866, 0xcd3565db, 0x8fcb5c05, 0x37128c11, "....." },
  [2561] = { nil, "Oben Rageclaw vuole che tu uccida il suo corpo senz'anima e poi usi il ⟦Voodoo Charm=Talismano Vudù⟧.", "Dopo aver esaminato questo talismano, {name}, ora capisco cosa bisogna fare. Ti prego, prendilo e fa' come ti chiedo.\n\nDevi esplorare le zone più profonde dell'⟦Ban'ethil Barrow Den=Eremo di Ban'ethil⟧. Lì troverai il mio corpo senz'anima... Anche se mi rammarico di ciò che sto per dirti, non vedo altro modo per liberarmi dal controllo dei ⟦Gnarlpine=Mordipigna⟧.\n\nPer sfuggire a loro, devi uccidere la mia forma fisica. Fatto questo, usa il talismano vudù sul mio corpo caduto. Dopo aver portato a termine questo compito, ti prego, torna da me.", "{name}, fai attenzione quando ti avvicini alla mia forma fisica: l'incantesimo che la vincola è molto potente.", "Finalmente sono libero dal controllo dei ⟦Gnarlpine=Mordipigna⟧. Grazie, {name}.\n\nOra il mio spirito potrà riposare in pace per sempre nel ⟦Emerald Dream=Sogno di Smeraldo⟧.\n\nForse un giorno ci incontreremo di nuovo, giovane {class}. Ma, per ora, accetta questa ricompensa come segno della mia gratitudine.", 0xdcee0406, 0x31a8c3fe, 0x9102b8db, 0x56e2ee75, 0x992edece, "e...." },
  [2607] = { "Il ⟦Touch of Zanzil=Tocco di Zanzil⟧", "Parla con Doc Mixilpixil nella cantina della caserma.", "Sembra che tu abbia riportato più informazioni di quante ne aspettassi perfino io. Questa è davvero una strana piega degli eventi, {name}.\n\nUna cura? Mmm... Scendi in cantina e parla con Doc Mixilpixil: forse può aiutarti.", nil, "Era ora! Metti il formaggio sul tavolo e sparisci. Osborne ti pagherà all'uscita.", 0x11470d66, 0xad163fb8, 0x32b769f3, nil, 0x006a9227, "...m." },
  [2608] = { "Il ⟦Touch of Zanzil=Tocco di Zanzil⟧", "/lay: sdraiati per farti visitare dal dottor Mixilpixil. Come può trovare la cura, se non trova la causa?", "Santo cielo, sembri la morte. Correggo: ho visto la morte, e tu sei mess<o/a> peggio. Tu, <signore/signorina>, sei quello che la morte ha tossito fuori alla sua ultima visita medica.\n\nAh! Hai sentito, Noarm? Scrivitela!\n\n*Coff* Ehm, sì, per aiutarti dovrò prelevarti un po' di sangue. Non preoccuparti, fa male solo le prime... cinquanta volte o giù di lì... Usa /lay e sdraiati quando sei pront<o/a> per la cura, {name}.", "Quando sei pront<o/a> per la visita, usa /lay, sdraiati a terra e comincerò il salasso.", "Dammi un momento per consultarmi con i miei colleghi, {name}. Dottor Montgomery, signor Noarm, a consulto!", 0x11470d66, 0xc7da4c18, 0x83e14b94, 0x27c52fde, 0x5baee4be, ".....", nil, nil, 0x0305c147, nil, nil },
  [2609] = { "Il ⟦Touch of Zanzil=Tocco di Zanzil⟧", "Porta al dottor Mixilpixil un mazzo di ⟦Simple Wildflowers=Fiori Semplici⟧, una Leaded Vial, un ⟦Bronze Tube=Tubo di Bronzo⟧ e una ⟦Spool of Light Chartreuse Silk Thread=Rocchetta di Filo di Seta Verdastro⟧. L'\"ite\" non guarisce da sola, <giovanotto/signorina>.", "È unanime, {name}. Hai l'\"ite\".\n\nPer fortuna ho una cura per l'\"ite\".\n\nEcco cosa mi serve: un mazzo di fiori semplici, una fiala piombata, un tubo di bronzo e, ultima ma non meno importante, una rocchetta di filo di seta verdastro. La vecchia Emma me ne ha lasciata una rocchetta a \"The Finest Thread\". Trovi il negozio lungo i canali.\n\nForza, sbrigati, {name}, e cerca di non toccare nessuno finché non sei guarit<o/a>. Ah, e il dottor Montgomery dice che hai bisogno di una doccia: parole sue, non mie.", "Se vuoi guarire dall'\"ite\" dovrai impegnarti più di così, {name}. Dove sono i reagenti per la cura?", "Cosa sto facendo? Secondo te cosa sto facendo? Sto preparando una cura per la tua \"ite\"! Non fare l'offes<o/a> adesso, {name}!\n\nAncora qualche secondo. Ecco! Spruzzati addosso questa, ehm, medicina dal profumo fantastico e sarai come nuov<o/a>.", 0x11470d66, 0xd6faf98a, 0xdeee9d37, 0x82beeccc, 0xfb99b7cf, ".....", nil, 0x6c5f6143, nil, nil, nil },
  [2745] = { "Infiltrarsi nel castello", "Parla con Tyrion nel Castello di ⟦Stormwind=Roccavento⟧.", "Mmm, una storia interessante, e da non prendere alla leggera. Sì, posso aiutarti, ma se vuoi andare fino in fondo dovrai amministrare una forma di giustizia che non è... legale.\n\nLescovar e Marzon vanno sistemati, e in fretta. Credi di essere all'altezza?\n\nDecidi tu. Se sì, corri al castello e trova un mio vecchio amico, uno gnomo di nome Tyrion. Tiene d'occhio Lescovar da un paio di settimane. Dovrebbe poterti aiutare a chiudere la faccenda.", nil, "Ma che...?! Non arrivarmi alle spalle così! E abbassa la voce! In nome dell'Ombra, che ci fai qui ad arrivarmi di soppiatto? Non vedi che ho da fare, razza di <stupido/stupida>?\n\nCome sarebbe, cosa sto facendo? Aspetto che si apra il prossimo Portale Oscuro, cosa diavolo credi che stia facendo? Di' quello che hai da dire e vattene... prima che le guardie notino noi due nascosti insieme tra i cespugli. Ho una reputazione da difendere.", 0x8aa81dca, 0xffe1ba3d, 0x31a5101a, nil, 0xd55e7590, "...m." },
  [2746] = { "Oggetti di una certa importanza", "Porta 3 ⟦Silk Cloth=Tessuto di Seta⟧ e 2 Mela Fresca di Clara a Tyrion, a ⟦Stormwind=Roccavento⟧.", "Trias vuole anticipare un po' i tempi, eh? D'accordo, si può fare, ma non sono pronto. E sappi questo: la parte difficile la faccio io, ma sei tu <quello/quella> che si sporcherà le mani, capito? Bene.\n\nAllora, prima di mettere in atto il mio piano mi serve che tu mi procuri alcune cose. Ho il travestimento perfetto per far passare Spybot davanti a quelle guardie.\n\nPortami un po' di seta e un paio di mele. Per la seta fai tu, ma la fattoria di Clara, appena fuori città, ha mele della misura perfetta.", "Tengo d'occhio Lescovar da un paio di settimane. Trias non si è mai fidato di lui, ma non sospettavamo che avesse a che fare con la ⟦Defias Brotherhood=Fratellanza dei Defias⟧. Stavamo seguendo piste che lo legavano al ⟦Twilight's Hammer=Martello del Crepuscolo⟧. In ogni caso, è diventato più pericoloso di quanto questa città possa gestire, ed è qui che entriamo in gioco noi.\n\nProcurami quegli oggetti e potremo mettere in atto il mio piano.", "Andranno benissimo, {name}. Ottimo lavoro.\n\nIl resto dell'attrezzatura che mi serve ce l'ho nello zaino... grazie alla Luce, ho appena fatto fare una borsa di seta a un mio amico sarto. Stavo finendo lo spazio per portarmi dietro tutta la roba.\n\nPrima che Spybot entri, definiamo i dettagli, così sai cosa devi fare.", 0x1f4eb590, 0x1d0c75b3, 0x1b56c1ff, 0xb3384936, 0x8b76d0c1, ".....", nil, nil, 0xde7d35a2, nil, nil },
  [2751] = { "Armamenti barbarici", "Porta 2 ⟦Patterned Bronze Bracers=Bracciali di Bronzo Decorati⟧, 2 Granspada di Bronzo e 2 Artiglio Affilato a Orokk Omosh a Orgrimmar.", "Venti generazioni di Omosh hanno impugnato questo martello, {name}. Centomila tonnellate di metallo abbiamo forgiato. Tragicamente, tutto finisce con Orokk, il fallimento degli Omosh: senza parenti e incapace di avere discendenti.\n\nNon posso lasciare che le ricette segrete degli Omosh muoiano con me! Qualcuno deve portare avanti l'eredità, Omosh o no!\n\nDimostra a Orokk che sei capace, {name}. Porta a Orokk quanto segue: due Bracciali di Bronzo Decorati, due Granspade di Bronzo e due Artigli Affilati. Portali a Orokk e andremo avanti.", "Bronzo, {name}! Altro bronzo!!", "La stirpe svanirà, ma forse la leggenda degli Omosh continuerà!\n\nHai dimostrato di essere un fabbro, {name}. Per il fabbro, la ricompensa è la soddisfazione di vedere le proprie armi e armature ricoperte del sangue dei nemici!\n\nChe le corazze che creerai per le generazioni future siano intrise del sangue dei tuoi nemici!", 0x17a1e905, 0x5f866922, 0x7a95f0a5, 0x718616f8, 0x90223961, "....." },
  [2752] = { "Sui paraspalle di ferro", "Porta 4 Ascia da Battaglia di Bronzo e 4 Martello da Guerra di Bronzo a Orokk Omosh a Orgrimmar.", "Orokk vede l'entusiasmo nei tuoi occhi, {name}. Come una spugna assorbi la saggezza degli Omosh.\n\nTre lezioni io insegnerò!\n\nTorna all'incudine, impregnati del calore della forgia e crea per Orokk quattro Asce da Battaglia di Bronzo e quattro Martelli da Guerra di Bronzo. Solo allora conoscerai il segreto del paraspalle di ferro.", "Mostrami la tua dedizione, {race}.", "Rendi fiero Orokk, {name}. Leggi e scopri i segreti dei paraspalle di ferro!", 0xf7581b4d, 0x57479f8c, 0xb4647cff, 0x31673690, 0x16d86607, "....." },
  [2753] = { "Schiacciati sotto i piedi", "Porta 4 Elmo di Ferro Verde, 4 ⟦Green Iron Bracers=Bracciali di Ferro Verdi⟧ e 2 ⟦Green Iron Leggings=Gambiere di Ferro Verdi⟧ a Orokk Omosh a Orgrimmar.", "Solo altre due lezioni Orokk insegnerà, {name}. I tuoi muscoli fanno male, lo so, ma continua per gli Omosh!\n\nPorta a Orokk quattro elmi di ferro verde, quattro bracciali di ferro verdi e due gambiere di ferro verdi: così tu impari e i tuoi nemici soffrono!", "I loro crani si spaccheranno sotto il peso dei tuoi stivali!", "Tu ricordi a Orokk suo nonno, il capo Gorokk degli Omosh! Leggi, impara dello stivale di ferro.", 0x910ff756, 0xaf1751cb, 0x89658ce5, 0x8fb855cc, 0x65ef0b88, "....." },
  [2754] = { "Corni della frenesia", "Porta 2 Maglio di Ferro Solido, 2 ⟦Silvered Bronze Boots=Stivali di Bronzo Argentato⟧ e 2 ⟦Silvered Bronze Gauntlets=Guanti di Bronzo Argentato⟧ a Orokk Omosh a Orgrimmar.", "L'ultima lezione che Orokk ti insegna, {name}. All'incudine e alla forgia sacre tu ritorni! Porta per Orokk due magli di ferro solido, due stivali di bronzo argentato e due guanti di bronzo argentato.\n\nGuarda la paura nei loro occhi quando ti avvicini!", "Mostra al ferro chi comanda, {name}!", "Stupefacente! Hai imparato la via degli Omosh, {name}!", 0xda80e91d, 0xcba97f38, 0xe496585c, 0x255ff424, 0xf310ad15, "....." },
  [2755] = { "Le gioie degli Omosh", "Guarda e impara la danza della gioia degli Omosh.", "Orokk non piange, {name}. Fuliggine in occhio.\n\n<Orokk si asciuga una lacrima.>\n\nC'è un ultimo segreto della famiglia Omosh che Orokk ti insegnerà. Orokk morirà felice, grazie a {name}.\n\nImpara danza della gioia degli Omosh e poi impari pugno di ferro!", nil, "<Orokk ansima.>\n\nÈ passato molto tempo da quando Orokk ha fatto la danza della gioia degli Omosh. Impara ora, {name}!", 0x69671f62, 0x90c19859, 0x16aecffb, nil, 0xc6b8ccc7, "...m." },
  [2756] = { "Le antiche usanze", "Porta 4 Pettorale Corazzato d'Acciaio e 4 Elmo d'Acciaio Runico ad Aturk l'Incudine, a Orgrimmar.", "Ai tempi delle leggende, Aturk frantumava i crani dei suoi nemici e ne macinava le ossa in una polvere sottile da usare come filamento. Quei giorni sono finiti da un pezzo, {race}. Il Capoguerra chiede la pace tra i clan. I vecchi nemici ora vengono solo osservati con occhi stanchi!\n\nIncredibile, lo so, ma tale è la volontà di Thrall.\n\nBasta lamentarsi! Sei qui per imparare, e imparerai! Portami quattro pettorali d'acciaio e quattro elmi d'acciaio e avrai un assaggio di guerra!", "Aturk, come il tempo, non aspetta nessuno! Sbrigati, idiota!", "A quanto pare sei solo un altro docile pecorone del Capoguerra, {name}. Che delusione.\n\nQuanto desidero una morte gloriosa sul campo di battaglia. E invece sono bloccato qui, per ordine di Thrall, a insegnare il mestiere ai poppanti! Guarda e impara, <pivello/pivella>!", 0x4e5f99d2, 0x111e7523, 0xd7eb3c98, 0xfa65622b, 0xd7251ac5, "....." },
  [2757] = { "⟦Booty Bay=Baia del Bottino⟧ o niente!", "Parla con McGavan alla ⟦Booty Bay=Baia del Bottino⟧.", "Ascolta, <ragazzo/ragazza>, non imparerai niente restando qui a gironzolare.\n\nConosco un tizio che conosce un tizio. Bazzica la fucina della ⟦Booty Bay=Baia del Bottino⟧. Se gli mostri questa insegna, ti racconterà tutto sul mithril.\n\nAllora, che ne dici? Lascia queste cose da principianti ai poppanti in fasce, {name}: è ora di andare avanti.\n\nSe ti interessa, si chiama McGavan. Mostragli questo ninnolo e riconoscerà il tuo impegno.", "Quelli come te sono una razza rara, compare. Fammi vedere quell'insegna.", "Per i peli della schiena di Blackhoof... finalmente qualcuno degno del Mithril Order!", 0x201687f5, 0x76671185, 0x8d214fc9, 0xbd77d15c, 0x83bb6990, "....." },
  [2758] = { "Le origini della forgiatura", "Porta 6 ⟦Golden Scale Bracers=Bracciali di Scaglie d'Oro⟧ a Hank il Martello, a ⟦Stormwind=Roccavento⟧.", "Quando avevo più o meno la tua età, un nano di nome Galvan mi prese sotto la sua ala e mi insegnò l'arte del fabbro d'armature. Prima di partire per la ⟦Booty Bay=Baia del Bottino⟧, mi fece promettere di addestrare tutti coloro che avessero il desiderio e la determinazione di progredire nell'arte della forgiatura; ed eccomi qui, dopo tutti questi anni.\n\nE ora è il momento che tu impari qualcosa. Fabbricami sei bracciali di scaglie d'oro e scoprirai da dove nasce la forgiatura, {name}.", "Potresti essere tu <il/la> prossim<o/a> protett<o/a> di Galvan?", "Molto bene, {name}! Ascolta e impara.\n\nLa forgiatura non nasce mai da qui! <Hank indica il suo martello.>\n\nLa forgiatura non nasce mai da qui! <Hank indica l'incudine.>\n\nLa forgiatura nasce solo da qui! <Hank indica il suo cuore.>\n\nE ora conosci l'origine della forgiatura.", 0x5dd39489, 0x350387d3, 0x870eb53b, 0x1e10ca8a, 0xeb39dca0, "....." },
  [2759] = { "In cerca di Galvan", "Parla con McGavan alla ⟦Booty Bay=Baia del Bottino⟧.", "Anche se Galvan ha lasciato la ⟦Booty Bay=Baia del Bottino⟧ molti anni fa, alcuni membri dell'ordine sono ancora in città, nella speranza di trovare un giorno qualcun altro degno degli insegnamenti di Galvan.\n\nPrendi questa insegna e presentala a McGavan, alla ⟦Booty Bay=Baia del Bottino⟧.\n\nSe davvero arrivi fin lì, saprà che ne sei degn<o/a>. Ho fiducia in te, {name}!", "Quelli come te sono una razza rara, compare. Fammi vedere quell'insegna.", "Per i peli della schiena di Blackhoof... finalmente qualcuno degno del Mithril Order!", 0x4dfe8db2, 0x76671185, 0x9fa6b639, 0xbd77d15c, 0x83bb6990, "....." },
  [2760] = { nil, "Parla con Galvan l'Antico nella Valle di Rovotorto.", "La maggior parte delle nostre reclute non arriva mai a ⟦Booty Bay=Baia del Bottino⟧, {name}. Lo scintillio dell'insegna basta a scatenare la brama di bottino anche nel più saldo dei fabbri. Che sciocchi, perché l'insegna è una goccia nel mare in confronto alle ricchezze che vedrai!\n\nTrova Galvan l'Antico e mostragli questa spilla. La sua dimora è molto a nord, tra Zul'gurub e il Tumulo degli Ogre Mosh'ogg.", "Salute! Avvicinati; mostra a Galvan cosa hai.", "Ah, sono passati molti anni dall'ultima volta che qualcuno si è dimostrato degno dell'iniziazione del Mithril Order. Cominciamo subito!", 0x569a9c64, 0xa93e34db, 0x8f04f385, 0x5db33734, 0x2f763df1, "e...." },
  [2769] = { "I fratelli Brassbolts", nil, nil, nil, nil, 0x089469a7, nil, nil, nil, nil, ".mmmm" },
  [2841] = { "Guerra di macchine", "Recupera i ⟦Rig Blueprints=Progetti Modificati⟧ e Thermaplugg's Safe Combination a Gnomeregan e portali a Nogg a Orgrimmar.", "La tecnologia degli gnomi: due anni fa la si usava soprattutto per farci battute. I tempi sono proprio cambiati. Ora hanno costruito una nuova macchina che è meglio di tutti i nostri modelli di segatronchi messi insieme. Mi servono i progetti, {name}!\n\nPurtroppo i progetti sono chiusi in una cassaforte vicino a Mekgineer Thermaplugg. E come se non bastasse, la combinazione della cassaforte la conosce solo Mekgineer Thermaplugg.\n\nFa' tutto quello che serve per avere quella combinazione, {name}. Poi apri quella cassaforte e riportami quei progetti!", "Non vedo nessun progetto. Li hai nascosti da qualche parte addosso o te ne stai qui solo per irritarmi?", "Sapevo che ce l'avresti fatta, {name}! Sovik invece aveva i suoi dubbi.\n\n<Nogg si schiarisce la gola.>\n\nOra che abbiamo i progetti, è solo questione di tempo prima di capire tutte le innovazioni degli gnomi che sono servite a costruire la macchina e trasformarle in innovazioni goblin per i nostri nuovi modelli di segatronchi.", 0xcf5a7376, 0x0da92dea, 0xe80d6917, 0xc41d80f1, 0xbb1889bb, "....." },
  [2842] = { "L'ingegnere capo Scooty", "Parla con Scooty alla ⟦Booty Bay=Baia del Bottino⟧.", "Appena Kernobee ci ha dato notizia della nuova macchina degli gnomi, io e Scooty ci siamo messi al lavoro sul Transpolyporter 6000: il modo più veloce e affidabile per arrivare a Gnomeregan.\n\nFinalmente è pronto a imbarcare passeggeri, {name}. Se vuoi provarlo, va' alla ⟦Booty Bay=Baia del Bottino⟧ e parla con Scooty al posatoio delle viverne. Per arrivare alla ⟦Booty Bay=Baia del Bottino⟧, prendi la nave da ⟦Ratchet=Porto Paranco⟧.\n\nCerto, potresti sempre tentare di raggiungere Gnomeregan attraverso le montagne di Dun Morogh infestate dai nani!", nil, "È una bellezza, vero? Il massimo della tecnologia goblin dei trasporti: è esplosa solo una dozzina di volte, più o meno.\n\nNon preoccuparti, {name}, l'ho sistemata per bene. Non ti esploderà sotto i piedi, e se succede, sarà rapido e indolore.", 0x8bca8052, 0xfcd92c6b, 0x7f138176, nil, 0xc0853908, "...m." },
  [2843] = { "Gnomeregan, arrivoooo!", "Aspetta che Scooty calibri il ⟦Goblin Transponder=Segnalatore dei Goblin⟧.", "Finché hai con te il segnalatore, devi solo salire sulla piattaforma e verrai teletrasportat<o/a> a Gnomeregan.\n\nPotresti avere qualche effetto collaterale insolito, ma nessuno dovrebbe essere permanente... non più.\n\nStavo quasi dimenticando la parte più importante: il ritorno. Quando vorrai tornare, sali sulla piattaforma del transpolyporter a Gnomeregan!\n\nOra calibro il segnalatore sulla tua taglia e sul tuo peso.", "È pronto!", "Fatto! Quando sei pront<o/a>, sali sulla piattaforma.", 0xbb614da5, 0xec9deafb, 0xed51c3c5, 0x8ea737cf, 0x32ca58dc, "....." },
  [2904] = { "Un bel pasticcio", "Scorta Kernobee fino all'uscita di Clockwerk Run, poi fai rapporto a Scooty a ⟦Booty Bay=Baia del Bottino⟧.", "<Kernobee geme.> Co... Cos'è successo?\n\nL'ultima cosa che ricordo è che un gruppo di nani Ferroscuro mi ha catturato, mi ha pestato fino a ridurmi in fin di vita e poi mi ha buttato qui dentro con questi trogg schifosi.\n\nTirami fuori di qui, {name}!\n\nEcco il piano: guidami all'uscita; se ne usciamo vivi, tu vai a ⟦Booty Bay=Baia del Bottino⟧ e fai sapere a Scooty che sono andato a ⟦Ratchet=Porto Paranco⟧ per avvertire Tinkerwiz del coinvolgimento dei Ferroscuro nella costruzione di quella supermacchina.\n\nAndiamo!", "Eh? Kernobee è vivo??", "Credo che tu meriti una ricompensa per averci riportato Kernobee tutto intero, {name}. Se tornerai a Gnomeregan, questi potrebbero darti il vantaggio che ti servirà per sconfiggere quel traditore buono a nulla, Mekgineer Thermaplugg.", 0x63147a20, 0xac5b2106, 0x2a36e481, 0x0aeeadf6, 0x70f50dab, "....." },
  [2922] = { "Salva il cervello di Techbot!", "Porta il ⟦Techbot's Memory Core=Nucleo della Memoria di Techbot⟧ al mastro inventore Overspark, a ⟦Ironforge=Forgiardente⟧.", "Quando la nostra amata città di Gnomeregan è caduta, una scintilla impazzita deve aver colpito la mia povera creazione, Techbot. Un tempo aiutava me e i miei colleghi con i suoi innumerevoli aggeggi e la sua scorta illimitata di informazioni, ma il suo cervello positronico si è polarizzato. Ora è negatronico... e i comportamenti di Techbot si sono invertiti. Vaga per Gnomeregan in preda alla frenesia!\n\nMa forse si può ancora salvare. Forse, se riesci a recuperare il nucleo della memoria di Techbot e a portarmelo, potrò scoprire la causa della polarizzazione e aggiustare il mio povero Techbot.", "Hai trovato Techbot? Hai recuperato il suo nucleo della memoria??", "Oh, è meraviglioso! Grazie, {name}! Mi metto subito al lavoro!!\n\nPovero, povero Techbot... Non abbatterti. Ti rimetteremo a posto.\n\nAllora, dove ho messo quella spina per la mia chiave girevole idro-cric...", 0x142b3f91, 0x989bf380, 0xa96aa51e, 0xa4a609b7, 0xbbc02495, "....." },
  [2923] = { "Il mastro inventore Overspark", "Parla con il mastro inventore Overspark, a ⟦Ironforge=Forgiardente⟧.", "Il mastro inventore Overspark è molto turbato per la sorte della sua creazione meccanica, Techbot. Ricordo Techbot come un aiutante gentile e utile per gli gnomi, ma Overspark mi dice che si è guastato.\n\nChe tristezza. Ma con un po' di fortuna forse si può aggiustare!\n\nParla con il mastro inventore Overspark, a Tinker Town, a ⟦Ironforge=Forgiardente⟧. Il tuo aiuto gli farebbe piacere.", nil, "Sì, è vero. Techbot è impazzito! Ti prego, puoi aiutarmi?", 0x50a40f08, 0x98ca0fa7, 0x226d20ab, nil, 0x8a6b241a, "...m." },
  [2924] = { "Essenziali Artificiali", "Porta 12 Essenziale Artificiale a Klockmort Spannerspan a ⟦Ironforge=Forgiardente⟧.", "Un componente meccanico quasi universale, l'essenziale artificiale, era utilissimo agli inventori e ai fabbri di Gnomeregan. Ma durante la fuga frenetica dalla nostra città, nessuno si è ricordato di portarne via neanche uno! E me ne serve una grande scorta per un lavoro che intraprenderò a breve.\n\nTi prego, entra a Gnomeregan e procurami degli essenziali artificiali. Li troverai nelle zone più profonde della nostra città, dentro contenitori chiamati estrapolatori artificiali.\n\nGrazie, {name}, e fai presto, ti prego!", "Hai gli essenziali artificiali?", "Li hai presi! Ora posso cominciare i miei nuovi esperimenti!\n\nNon so come ringraziarti, {name}! Il tuo coraggio ha fatto fare alla ricerca gnomesca un balzo da gigante!", 0xd3e977d4, 0xc9a42ec8, 0xf08a62a3, 0x88153ec4, 0x0a9e26a6, "....." },
  [2925] = { "Gli essenziali di Klockmort", "Parla con Klockmort Spannerspan a ⟦Ironforge=Forgiardente⟧.", "Un amico gnomo, Klockmort Spannerspan, mi ha mandato un messaggio da ⟦Ironforge=Forgiardente⟧. Dice che ha bisogno di aiuto per una missione pericolosa ma essenziale dentro Gnomeregan, la città un tempo grandiosa degli gnomi, ora contaminata e piena di gnomi impazziti e dei loro congegni.\n\nIo devo restare qui, ma mi si stringe il cuore a non poter aiutare il mio amico. Se puoi andare al posto mio, te ne sarò molto grat<o/a>.\n\nTroverai Klockmort a Tinkertown, a ⟦Ironforge=Forgiardente⟧.", nil, "Sì! Sì che mi serve aiuto per una missione dentro Gnomeregan. E tu sei proprio <il/la> {class} che fa al caso mio!", 0xd1472bfc, 0x7fe3166f, 0x3f0bf57e, nil, 0x578dfce4, "...m." },
  [2926] = { nil, "Usa la ⟦Empty Leaden Collection Phial=Fiala della Raccolta Vuota⟧ sugli Irradiated Invader o sugli Irradiated Pillager per raccogliere le scorie radioattive. Quando è piena, riportala a Ozzie Togglevolt, a Kharanos.", "Dall'incidente, Gnoarn non fa che pensare e parlare di ripulire Gnomeregan dall'infestazione dei trogg e di trovare una cura per il morbo che la affligge, {name}.\n\nPer fortuna, io e Razzle siamo vicini a una specie di cura... o a quello, o alla ricetta di un rum davvero potente. Non lo sapremo finché non lo proviamo! Naturalmente, per verificare la nostra teoria, ci serviranno alcune cose: nella fattispecie, le scorie dei trogg irradiati di Gnomeregan. Riempi questa fiala di quel bagliore verde e riportamela!", "Non vedi che qui stiamo cercando di curare un'intera specie di gnomi??! Ci serve altro bagliore verde!", "Ottimo lavoro! È giunto il momento di provare la nuova formula. Se funziona, non solo quello gnomo lebbroso catturato dovrebbe guarire, ma io dovrei ritrovarmi con una chioma folta! Stai indietro!", 0xf0c05f18, 0xdf69f0fb, 0xa76f5528, 0x20727b89, 0x9b4aacb0, "e...." },
  [2927] = { "Il giorno dopo", "Parla con Ozzie Togglevolt, a Kharanos.", "Non penserai che io sia sempre stato calvo, vero? No, <signore/signora>! È stata la fuga radioattiva di Gnomeregan a causare questa tragica perdita di capelli. Prima di quel giorno avevo l'unico gnomafro di tutta Azeroth.\n\n<Gnoarn agita il pugno in aria.>\n\nMaledetti quei maledetti sudici trogg! Che siano maledetti tutti!!\n\nForse non è troppo tardi, {name}. Potremmo ancora salvarla... la città, intendo! Parla con Ozzie Togglevolt a Kharanos. Lui e il suo socio Razzle stanno lavorando a una soluzione.", nil, "Pensavo che la perdita di quella splendida chioma sarebbe stata di sicuro la sua fine, ma è sopravvissuto!\n\nEro proprio accanto a lui quando è stato colpito dal raggio di radiazioni. Quelle deliziose ciocche castane sono cadute a terra a ciuffi! A grappoli! L'orrore è stato solo aggravato quando Gnoarn è andato completamente fuori di testa! Oh sì, fuori di testa, ti dico! Gnoarn si è toccato la testa calva, incredulo, e il suo sguardo gridava vendetta, {name}! Poi ha rivolto la sua rabbia contro i trogg!\n\n<Ozzie rabbrividisce.>", 0xf43f453e, 0xba99320a, 0x80d33f0e, nil, 0xbb58d6a8, "...m.", nil, nil, 0xb6251687, nil, nil },
  [2928] = { "Escavatori girotrivellomatici", "Porta ventiquattro Robo-mechanical Guts a Shoni a ⟦Stormwind=Roccavento⟧.", "È terribile, {name}. Non avremo abbastanza pezzi per portare la nostra flotta di escavatori girotrivellomatici fino a Dun Morogh.\n\nCi servono pezzi di ricambio, {name}. E quale posto migliore di Gnomeregan per trovare i ricambi per i nostri veicoli? Ho sentito che là dentro robot e macchinari vagano come bestiame al pascolo.\n\nVoglio che tu vada a Gnomeregan e faccia a pezzi quei robot. Portami le loro budella robotiche. Due dozzine dovrebbero bastare.", "Se fosse una gara, avresti già perso.", "Andrà benissimo, {name}. Un escavatore girotrivellomatico riparato; ne restano 398.", 0x7c11ff31, 0x78ec2936, 0x740676eb, 0x3fc85274, 0xaf06627a, "....." },
  [2929] = { "Il grande tradimento", "Va' a Gnomeregan e uccidi Mekgineer Thermaplugg. Torna dall'alto inventore Mekkatorque quando avrai finito.", "Mi fidavo di Thermaplugg, {race}. Non mi sarei mai aspettato che tradisse me e l'intero popolo degli gnomi. E per cosa? Potere? Ricchezza? Tutte cose che col tempo avrebbe avuto. Ora siamo stati cacciati dalla nostra casa e quel pazzo comanda. Il re del nulla...\n\nRiprenderemo Gnomeregan, {name}. Non ci fermeremo finché la città non sarà di nuovo sotto il nostro controllo. Se vuoi unirti alla nostra lotta, ti chiedo un compito semplice: uccidi il traditore. Distruggi Mekgineer Thermaplugg.", "Il compito è fatto? Ha implorato clemenza? Pietà??", "Mi piace pensare che l'ultima cosa che gli è passata per la testa mentre crollava a terra sia stato il tuo piede, {race}. Con Thermaplugg morto, i nostri piani per riprendere Gnomeregan sono un passo più vicini a diventare realtà.", 0xc7223d52, 0xfb52e324, 0x8bff6fc1, 0xada3365b, 0x5ff1117b, "....." },
  [2930] = { "Recupero dati", "Porta una ⟦Prismatic Punch Card=Scheda Perforata Prismatica⟧ al maestro meccanico Castpipe a ⟦Ironforge=Forgiardente⟧.", "Quando siamo fuggiti da Gnomeregan, abbiamo lasciato indietro un sacco di dati! Dati di vitale importanza!\n\nMi servono i dati su una scheda perforata prismatica, da un terminale ad alta sicurezza Matrix Punchograph 3005-D, nel profondo di Gnomeregan. Devi accedere al terminale, ma per farlo ti serve prima un'autorizzazione... e per averla devi accedere ai terminali a sicurezza inferiore, i modelli -A, -B e -C. E per fare QUESTO ti servono le schede perforate di sicurezza, a cominciare da quella bianca... e abbiamo lasciato tutte le schede perforate in città.\n\nÈ una catastrofe! Puoi aiutarci?", "Hai la scheda perforata prismatica??", "Ce l'hai fatta! Hai trovato la scheda perforata prismatica e recuperato i dati perduti! Dati vitalmente, criticamente, incommensurabilmente importanti, senza i quali non potevamo vivere un istante di più!\n\nIl tuo servizio agli gnomi sarà ricordato a lungo, {name}.", 0xb572ead8, 0x0d6cb3dd, 0x5be7a1ee, 0xa5d0b260, 0x9a4bbb5a, "....." },
  [2931] = { "L'incarico di Castpipe", "Parla con il maestro meccanico Castpipe a ⟦Ironforge=Forgiardente⟧.", "Il maestro meccanico Castpipe di ⟦Ironforge=Forgiardente⟧ ha bisogno di avventurieri! Sta organizzando delle squadre per rientrare a Gnomeregan in una missione di recupero dati della massima segretezza e importanza.\n\nCastpipe non sarà un membro della Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences come me, ma è comunque uno gnomo sveglio, quindi se pensa che sia importante, secondo i miei calcoli c'è un ottantaquattro per cento di probabilità che lo sia davvero!\n\nSono buone probabilità!", nil, "Sto organizzando missioni di estrazione dati a Gnomeregan. Se sei qui per questo, allora ascolta bene!", 0x95ff10c3, 0x3809bbd3, 0x4d68d41f, nil, 0x3d0d0c09, "...m." },
  [2935] = { "Consulta il maestro Gadrin", "Parla con il maestro Gadrin al ⟦Sen'jin Village=Villaggio di Sen'jin⟧.", "Il veleno delle guardie della covata non era potente quanto quello che mi avevi portato all'inizio. Dev'essere venuto da un altro ragno.\n\nVoglio un campione fresco di quel veleno. Per scoprire da dove viene, devi consultare un troll che conosce bene i Witherbark: il maestro Gadrin, al ⟦Sen'jin Village=Villaggio di Sen'jin⟧. Recati a Durotar e parla con Gadrin. Con un po' di fortuna, saprà dove i Witherbark prendono il loro veleno.", nil, "Ah, quindi vuoi veleno fresco dal ragno dei Witherbark, eh? Be', siediti... quello che devo dirti non ti piacerà.", 0xf6fc7c51, 0x0c77979e, 0x4a620828, nil, 0x49a2f284, "...m." },
  [2945] = { "⟦Grime-Encrusted Ring=Anello Sudicio⟧", "Trova un modo per togliere lo sporco dall'⟦Grime-Encrusted Ring=Anello Sudicio⟧.", "Hai trovato quello che sembra un anello sul cadavere di uno dei nani ⟦Dark Iron=Ferroscuro⟧. È difficile dire che tipo di anello sia, però: terra e incrostazioni indurite lo ricoprono del tutto, ed è impossibile indossarlo. Ti sembra di scorgere la leggera lucentezza di un metallo prezioso, e forse persino il luccichio di una gemma sotto lo sporco.\n\nSe vuoi servirti di questo anello, dovrai trovare qualcosa per togliergli le incrostazioni.", "Il congegno gnomesco davanti a te porta una targa che lo chiama «Lo Sparklematic 5200». Dalle istruzioni sotto la targa si capisce che la macchina serve a togliere lo sporco da un oggetto. La macchina ha una fessura per le monete e, una volta messo dentro l'oggetto, accetta tre monete d'argento per avviare il processo.\n\nSembra proprio che l'anello incrostato che hai trovato prima sia la cosa giusta da provare in questa macchina!", "Metti l'anello nello Sparklematic 5200 e infili una moneta d'argento nella fessura.\n\nDalla macchina escono penosi rumori di ingranaggi, mentre comincia a scuotersi violentemente. Si può solo immaginare cosa stia succedendo all'anello là dentro...\n\nLa macchina si ferma di colpo e annuncia la fine con un semplice «Ding!». Lo scomparto si apre e rivela una scatolina incartata con cura, con un fiocco rosso. A quanto pare lo Sparklematic 5200 fa anche i pacchetti regalo!", 0xf8a3263a, 0xc110cf2f, 0xab7d0f3c, 0x344cc60a, 0x3a2498fd, "....." },
  [2947] = { "La restituzione dell'anello", "Puoi tenere l'anello, oppure cercare la persona a cui si devono il sigillo impresso e le incisioni all'interno della vera.", "Aprendo la scatola prodotta dallo Sparklematic 5200 trovi ciò che sospettavi: un anello lucente! Indossandolo, senti un potere magico scorrerti nel corpo.\n\nAll'interno della vera c'è un'impronta piccola ma ben riconoscibile del sigillo di ⟦Ironforge=Forgiardente⟧. Accanto sono incise tre piccole iniziali: \"TdK\". Potrebbero essere le iniziali del precedente proprietario, o forse quelle di chi ha forgiato l'anello. Tenere l'anello... o restituirlo a questa persona? Decisioni, decisioni...", "Ehi, calma, compare! Sono un uomo d'affari molto importante! Sono sicuro che il corriere è solo in ritardo con la consegna dell'affitto... aspetta... tu non sei il mio padrone di casa.\n\nMa certo che non lo sei, che sciocco! Sei venut<o/a> da me in cerca del miglior gioielliere di tutta ⟦Ironforge=Forgiardente⟧, uno che NON fa oggetti MALEDETTI! Sì!\n\nEhm... che cosa ti serve?", "Un anello, dici? Vediamo... sì, quell'anello l'ho fatto io, perbacco.\n\nPrima che Gnomeregan saltasse in aria, avevo una piccola bottega laggiù. Forse è uno di quelli che ho lasciato quando me la sono data a gambe; è un modello semplice, e ne ho fatti diversi così. Magari è di qualcuno che non è riuscito a uscirne.\n\nCe l'avevano i nani Ferroscuro? Be', questo aggiunge un nuovo strato di complotto ai nove strati che già girano. Forse alle autorità interesserebbe saperlo; con me è sprecato.\n\nOra, torniamo all'anello...", 0x9b2297a2, 0x8cbc1bad, 0x463d3a78, 0xf03132b6, 0x9157f220, "....." },
  [2948] = { "Migliorie da gnomo", "Porta l'⟦Brilliant Gold Ring=Anello d'Oro Scintillante⟧, un ⟦Silver Bar=Lingotto d'Argento⟧, un'⟦Moss Agate=Agata Muschiata⟧ e 30 monete d'argento a Talvash del Kissel a ⟦Ironforge=Forgiardente⟧.", "Senti, {name}, quell'anello è tuo, certo... ma io posso fartene uno migliore! Quel disegno, come ti dicevo, è davvero semplice. Ora sono molto più abile, e per la modica cifra di trenta monete d'argento te lo rimetto a nuovo! Be', un po' più di trenta, in realtà...\n\nAl momento sono in difficoltà: le mie scorte di materiali sono tutte esaurite. Se mi porti un lingotto d'argento e un'agata muschiata, aggiungerò all'anello un intreccio d'argento e agata che gli darà un tocco in più!\n\nFidati di me!", "Hai i materiali che mi servono? Non te li chiederei se la sorte non mi avesse voltato le spalle...", "Ah, proprio quello che mi serviva! Un giorno, quando uscirò da questo buco in cui mi trovo ingiustamente, farò per te, anzi per TUTTI, i ninnoli più belli di tutta Azeroth! Fino ad allora, grazie per essere stat<o/a> così sportiv<o/a> con i reagenti. Di solito per un anello di questa qualità chiederei dieci volte quello che ho chiesto a te...\n\nA proposito di anelli, ecco il tuo nuovo anello!", 0xaf868c64, 0x1a07e711, 0x8547b93f, 0x965ed2bb, 0xd8803d0d, "....." },
  [2949] = { "La restituzione dell'anello", "Puoi tenere l'anello, oppure cercare la persona a cui si devono il sigillo impresso e le incisioni all'interno della vera.", "Aprendo la scatola prodotta dallo Sparklematic 5200 trovi un anello lucente! Infilandolo, senti un potere magico scorrerti nel corpo.\n\nAll'interno della vera c'è un'impronta piccola ma ben riconoscibile del sigillo di Orgrimmar. Accanto ci sono delle lettere incise, ma anche dopo la pulizia si distinguono solo le prime tre: \"NOG...\"\n\nPotrebbero essere le iniziali del precedente proprietario, o forse quelle di chi ha forgiato l'anello. Tenere l'anello... o trovare \"NOG\"? Decisioni, decisioni...", "Uno penserebbe che troveremmo da soli un modo per superare quei piccoli gnomi schifosi. Scommetterei persino che quel marchingegno l'hanno rubato a noi, tanto per cominciare! Bah, quei viscidi, luridi... ehm, sì? Ti serve qualcosa?", "Un anello di Gnomeregan? Vediamo... non è mio, ma è interessante.\n\nLa faccenda di Gnomeregan... non poteva capitare a un branco di zucconi più simpatici. Per anni sono stati una barzelletta, e ora, quasi da un giorno all'altro, costruiscono macchinari migliori dei nostri?\n\nCe l'avevano i nani Ferroscuro? Questo è ancora più interessante! Sai, magari gli gnomi hanno rubato i loro folli progetti di golem e li hanno modificati. Quei Ferroscuro vorrebbero di sicuro una bella vendetta. Vale senz'altro la pena di indagare.\n\nSai, a proposito di quell'anello...", 0x9b2297a2, 0x8cbc1bad, 0xb84d59f3, 0xe22ff9bc, 0x4e5317a9, "....." },
  [2950] = { "L'anello rifatto di Nogg", "Porta l'⟦Brilliant Gold Ring=Anello d'Oro Scintillante⟧, un ⟦Silver Bar=Lingotto d'Argento⟧, un'⟦Moss Agate=Agata Muschiata⟧ e 30 monete d'argento a Nogg a Orgrimmar.", "No, no, no: non sto dicendo all'improvviso che l'anello è mio. Di solito non lo faccio, ma le tue informazioni sui Ferroscuro sono state utilissime. Ti migliorerò l'anello, meglio di quanto avrebbe mai potuto fare chiunque abbia fatto questa cosetta semplice. Probabilmente qualche gnomo...\n\nSe mi porti un lingotto d'argento, un'agata muschiata e trenta monete d'argento per il disturbo, aggiungerò all'anello un intreccio d'argento e agata che rafforzerà la magia al suo interno. Ti interessa?", "Hai i materiali che mi servono? Non posso migliorare questo disegno senza tutto quello che ti ho chiesto.", "Ecco il tuo anello, meglio di prima. Grazie ancora per le informazioni su quei nani ⟦Dark Iron=Ferroscuro⟧. Mi sembra una pista ragionevole per capire come quegli gnomi siano stati colpiti all'improvviso da un'ispirazione degna dei goblin.", 0xe9be8e28, 0xc0fbbadd, 0x13b26acd, 0x95624713, 0x48a5420b, "....." },
  [2951] = { "Lo Sparklematic 5200!", "Inserisci un Grime-Encrusted Item nello Sparklematic 5200, e assicurati di avere tre monete d'argento per avviare la macchina.", "Questo marchingegno spicca tra gli gnomi che resistono alla follia fuori dalla stanza. Una piccola targa sul congegno dice «Lo Sparklematic 5200», seguita da un testo:\n\n«Sporcizia e incrostazioni rovinano i tuoi gioiellini? Lo Sparklematic 5200 rimette lo splendore nello splendidoso! Inserisci l'oggetto che vuoi pulire e deposita tre monete d'argento nella fessura. Concedi allo Sparklematic 5200 un momento per l'operazione, e voilà! I tuoi oggetti di valore usciranno puliti e scintillanti!»", "A quanto pare il congegno ha bisogno di un qualche oggetto incrostato di sporcizia da pulire e di tre monete d'argento per mettersi in funzione. Se ci sono entrambe le cose, lo Sparklematic 5200 dovrebbe funzionare...", "Inserisci l'oggetto incrostato di sporcizia e tre monete d'argento nello Sparklematic 5200. La macchina si risveglia in un tentativo frenetico di eliminare la sporcizia dall'oggetto sconosciuto. Dal cuore della macchina arrivano rumori violenti e assordanti di sbattimento. Il telaio di metallo del bestione cigola e geme mentre sobbalza da una parte all'altra...", 0x7df37d0f, 0xa77d0758, 0x66b0513f, 0x38e80812, 0x55272153, "....." },
  [2952] = { "Lo Sparklematic 5200!", nil, nil, nil, "Così come era partito, lo Sparklematic 5200 si ferma di colpo. Dalla macchina si sente un semplice \"ding\" e la sua bocca si apre a spirale verso l'alto. Dentro lo Sparklematic 5200 c'è una scatoletta legata con un fiocchetto. A quanto pare la macchina incarta l'oggetto dopo averlo liberato dalla sua crosta di sporcizia. Anche se la macchina non avesse funzionato, almeno ora l'oggetto è incartato in una bella scatola.\n\nBe', c'è un modo per scoprire se l'ha pulito o no...", 0x7df37d0f, nil, nil, nil, 0x6b359458, ".mmm." },
  [2962] = { "L'unica cura è altro bagliore verde", "Va' a Gnomeregan e riporta della ⟦High Potency Radioactive Fallout=Ricaduta Radioattiva ad Alta Potenza⟧. Attenzione: la ricaduta è instabile e decade piuttosto in fretta.\n\nAl termine del compito, Ozzie vorrà anche la tua ⟦Heavy Leaden Collection Phial=Fiala della Raccolta Pesante⟧.", "Non solo il tuo campione era insufficiente come quantità, era anche impuro.\n\nCi serve altro bagliore verde. È evidente che i trogg non sono abbastanza irradiati per le nostre esigenze. Dovrai andare a Gnomeregan e riportare della ricaduta radioattiva, presa direttamente alla fonte. Parlo delle melme, dei predatori in agguato e degli orrori irradiati. Attenzione: contenere questo tipo di ricaduta è difficile. Potrebbero servirti diversi tentativi con la fiala prima di raccogliere un campione adatto.", "Mmh, non brilli. È un buon segno.", "<Ozzie ti esamina.> Notevole, hai ancora tutti gli arti. Ora vediamo cosa sa fare questa roba!", 0xc891dea0, 0x4e7ea0ad, 0x6fc2256f, 0x66e8e057, 0x6eeec372, "....." },
  [2967] = { "Ritorno a ⟦Thunder Bluff=Picco del Tuono⟧", nil, nil, nil, nil, 0xb5d4ecc4, nil, nil, nil, nil, ".mmmm" },
  [2983] = { "Il richiamo del fuoco", "Trova Kranal Fiss nelle ⟦Barrens=Savane⟧.", "È passato un po' di tempo dalla tua ultima prova, {name}. Finora sei <stato/stata> paziente nei tuoi studi, ma è ora che tu conosca poteri più grandi... è ora che tu conosca il vero potere. L'elemento del fuoco è tuo, se sei dispost<o/a> a pagarne il prezzo.\n\nCerca Kranal Fiss nelle ⟦Barrens=Savane⟧. Vive in una piccola dimora a nord del ⟦Crossroads=Crocevia⟧, ma fai attenzione: se hai raggiunto quelle maledette terre degli elfi della notte, sei andat<o/a> decisamente troppo oltre.", nil, "Mmm, ti ha mandato Swart da me, vero?\n\nBe', di Swart ci si è sempre potuti fidare, quindi vuol dire che sei pront<o/a> a prendere parte alla prossima sapta: la sapta del fuoco.\n\nLo vedo già nei tuoi occhi, l'ardore, il desiderio. Hai assaggiato il potere e ora ne vuoi ancora. Pazienza, {name}. Ricorda ciò che ti ha insegnato la terra. Potere e distruzione arriveranno facilmente, ma devi comunque sapere quando trattenere la mano.", 0x53f3b76b, 0xb1158d84, 0x0c7a07c5, nil, 0xbe75ed09, "...m." },
  [2984] = { "Il richiamo del fuoco", "Trova Kranal Fiss nelle ⟦Barrens=Savane⟧.", "È passato molto tempo dall'ultima volta che sei <stato/stata> mess<o/a> alla prova, {name}. Finora hai mostrato pazienza nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la distruzione... e il caos. L'elemento del fuoco è tuo da comprendere, se sei pront<o/a> a pagarne il prezzo.\n\nCerca Kranal Fiss nelle ⟦Barrens=Savane⟧. Vive in una piccola dimora a nord del ⟦Crossroads=Crocevia⟧, ma fa' attenzione: se sei arrivat<o/a> nelle terre degli elfi della notte, sei andat<o/a> troppo lontano.", nil, "Mmm, ti ha mandato Narm da me, vero?\n\nBe', di Narm ci si è sempre potuti fidare, quindi vuol dire che sei pront<o/a> a prendere parte alla prossima sapta: la sapta del fuoco.\n\nLo vedo già nei tuoi occhi, l'ardore, il desiderio. Hai assaggiato il potere e ora ne vuoi ancora. Pazienza, {name}. Ricorda ciò che ti ha insegnato la terra. Potere e distruzione arriveranno facilmente, ma devi comunque sapere quando trattenere la mano.", 0x53f3b76b, 0xb1158d84, 0x0f02e651, nil, 0xd20cd47c, "...m." },
  [2985] = { "Il richiamo dell'acqua", "Trova Islen Waterseer nelle ⟦Barrens=Savane⟧.", "Sembri pront<o/a> per la tua prossima prova, {name}. Sei stat<o/a> paziente nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la purezza dell'acqua.\n\nCerca Islen Waterseer nelle ⟦Barrens=Savane⟧. Si trova lungo la costa orientale, a sud del ⟦Southfury River=Fiume Furialunga⟧ e di ⟦Ratchet=Porto Paranco⟧. La troverai lì, nella sua capanna da pesca. Buona fortuna, {name}.", nil, "Il vento ti viene incontro veloce dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già scaldato dal fuoco: direi che è giunto il momento di conoscere la purezza dell'acqua.\n\nIl tuo cammino ti ha portato fin qui, e il tuo spirito ti darà la forza di andare ancora più lontano. Ma il primo passo spetta a te.", 0x1f0e11aa, 0x52f30fbd, 0x2f9a1a5e, nil, 0xf9228c66, "...m." },
  [2986] = { "Il richiamo dell'acqua", "Trova Islen Waterseer nelle ⟦Barrens=Savane⟧.", "È passato molto tempo dalla tua ultima prova, {name}. Finora hai mostrato pazienza nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la purezza dell'acqua.\n\nCerca Islen Waterseer nelle ⟦Barrens=Savane⟧. Si trova lungo la costa orientale, a sud del ⟦Southfury River=Fiume Furialunga⟧ e di ⟦Ratchet=Porto Paranco⟧. La troverai lì, nella sua capanna da pesca. Buona fortuna, {name}.", nil, "Il vento ti viene incontro veloce dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già scaldato dal fuoco: direi che è giunto il momento di conoscere la purezza dell'acqua.\n\nIl tuo cammino ti ha portato fin qui, e il tuo spirito ti darà la forza di andare ancora più lontano. Ma il primo passo spetta a te.", 0x1f0e11aa, 0x52f30fbd, 0x7363625e, nil, 0xf9228c66, "...m." },
  [2996] = { "In cerca di Strahad", "Parla con Strahad Farsan a ⟦Ratchet=Porto Paranco⟧.", "In passato ti ho insegnato delle abilità, ma è giunto il momento che sia un altro a istruirti. Si trova a ⟦Ratchet=Porto Paranco⟧ e il suo nome è Strahad. È umano, ma non lasciarti ingannare: non è debole. È potente, anche se forse è piccolo. Può insegnarti evocazioni più potenti: sento che sei pront<o/a>. Va' da lui, ora. È a ⟦Ratchet=Porto Paranco⟧... sopra la città portuale, accanto alla sua torre.", nil, "Una giornata piena a ⟦Ratchet=Porto Paranco⟧, vero? Quanto mi piace osservare la fatica di una città portuale. Tanto mistero, tanta avventura... tanta ignoranza.\n\nÈ odio quello che vedo nei tuoi occhi, {name}? Bene, lo metteremo a frutto.", 0x884bfbbe, 0x0c866240, 0x442728fe, nil, 0x44d961f5, "...m." },
  [2997] = { "⟦Tome of Divinity=Tomo della Divinità⟧", "Parla con Tiza Battleforge a ⟦Ironforge=Forgiardente⟧.", "Salve, {name}. So che sei impegnat<o/a> ad aiutare la gente di Dun Morogh, ma quando hai tempo dovresti salire a ⟦Ironforge=Forgiardente⟧ a parlare con una delle nostre più rispettate: Tiza Battleforge. È da lei che vanno i paladini più giovani quando è il momento di imparare di più sulla Luce e su cosa ci si aspetta da te.\n\nLa trovi al piano di sopra, nella Hall of Mysteries. Se non ci sei mai stat<o/a>, è nel Mystic Ward. Buona fortuna, {name}.", nil, "Ben trovat<o/a>, {name}. Spero che la Luce ti mostri il vero cammino e ti protegga dal male.", 0x85861feb, 0x04be03fc, 0x4e98a6c9, nil, 0x942f654d, "...m." },
  [2998] = { "⟦Tome of Divinity=Tomo della Divinità⟧", "Parla con Duthorian Rall a ⟦Stormwind=Roccavento⟧.", "Salute, <fratello/sorella>. Duthorian Rall, uno dei nostri paladini più influenti, parlava di te di recente. L'ho sentito dire che era ora di metterti un po' alla prova... e anche dire cose molto lusinghiere su come te la sei cavata finora.\n\nSe fossi in te, andrei a ⟦Stormwind=Roccavento⟧ a parlargli quando hai tempo. Di sicuro è nella ⟦Cathedral of Light=Cattedrale della Luce⟧: è lì che passa la maggior parte del suo tempo.", nil, "È bello qui a ⟦Stormwind=Roccavento⟧, non trovi?\n\nA dire il vero, non potevi arrivare in un momento migliore, {name}.", 0x85861feb, 0x0f3ca705, 0x35944d83, nil, 0x3fd2197e, "...m.", nil, nil, 0xa8a5e826, nil, nil },
  [2999] = { "⟦Tome of Divinity=Tomo della Divinità⟧", "Parla con Tiza Battleforge a ⟦Ironforge=Forgiardente⟧", "Salve, {name}. So che sei impegnat<o/a> ad aiutare la gente di Dun Morogh, ma quando hai tempo dovresti salire al piano di sopra a parlare con una delle nostre più rispettate: Tiza Battleforge. È da lei che vanno i paladini più giovani quando è il momento di imparare di più sulla Luce e su cosa ci si aspetta da te.", nil, "Ben trovat<o/a>, {name}. Spero che la Luce ti mostri il vero cammino e ti protegga dal male.", 0x85861feb, 0xafea0004, 0xdacc6f34, nil, 0x942f654d, "...m." },
})
